// Compendium Explorer — vanilla JS, no build step.
// Data comes from data/*.json, generated by tools/build_data.py.
(() => {
  "use strict";

  // ------------------------------------------------------------ constants
  const CATS = {
    "verb": { label: "Keyword", group: "Subclass" },
    "fragment": { label: "Fragment", group: "Subclass" },
    "aspect": { label: "Aspect", group: "Subclass" },
    "super": { label: "Super", group: "Subclass" },
    "grenade": { label: "Grenade", group: "Subclass" },
    "melee": { label: "Melee", group: "Subclass" },
    "class-ability": { label: "Class ability", group: "Subclass" },
    "class-trait": { label: "Class trait", group: "Subclass" },
    "exotic-armor": { label: "Exotic armor", group: "Exotics", exotic: true },
    "exotic-weapon": { label: "Exotic weapon", group: "Exotics", exotic: true },
    "exotic-class": { label: "Exotic class item perk", group: "Exotics", exotic: true },
    "armor-set": { label: "Armor set bonus", group: "Armor" },
    "armor-mod": { label: "Armor mod", group: "Armor" },
    "artifact-perk": { label: "Artifact perk", group: "Armor" },
    "weapon-trait": { label: "Weapon trait", group: "Weapons" },
    "origin-trait": { label: "Origin trait", group: "Weapons" },
    "intrinsic": { label: "Weapon frame", group: "Weapons" },
    "weapon-mod": { label: "Weapon mod", group: "Weapons" },
    "weapon-info": { label: "Weapon info", group: "Weapons" },
    "mechanic": { label: "Activity modifier", group: "Mechanics" },
  };
  const ELEMENTS = ["Arc", "Solar", "Void", "Stasis", "Strand", "Prismatic"];
  const CLASSES = ["Hunter", "Titan", "Warlock"];
  // keyword groups worth turning into links inside descriptions
  const LINK_GROUPS = new Set(["Arc", "Solar", "Void", "Stasis", "Strand", "Prismatic"]);
  const LINK_EXTRA = new Set(["Orb of Power", "Armor Charge", "Elemental Pickup", "Elemental Buff", "Elemental Debuff", "Finisher"]);

  // ------------------------------------------------------------ state
  const S = {
    entries: [], byId: new Map(), keywords: [], kwByName: new Map(), meta: null,
    shared: {}, tables: null, sheets: {}, combined: null, glossary: new Map(),
  };
  const app = document.getElementById("app");

  // ------------------------------------------------------------ utils
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const h = (html) => { const t = document.createElement("template"); t.innerHTML = html.trim(); return t.content; };
  const store = {
    get(k, d) { try { const v = localStorage.getItem(k); return v ? JSON.parse(v) : d; } catch { return d; } },
    set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch { /* private mode etc. */ } },
  };
  const parseHash = () => {
    const raw = location.hash.replace(/^#\/?/, "");
    const [path, query = ""] = raw.split("?");
    return { parts: path.split("/").filter(Boolean).map(decodeURIComponent), q: new URLSearchParams(query) };
  };
  const go = (hash, replace = false) => {
    if (replace) history.replaceState(null, "", hash); else history.pushState(null, "", hash);
    route();
  };
  const sheetUrl = (src, tabName) => {
    const m = S.meta?.sources?.[src];
    if (!m) return null;
    const tab = m.tabs.find((t) => t.name === tabName);
    return `https://docs.google.com/spreadsheets/d/${m.id}/edit${tab ? `#gid=${tab.gid}` : ""}`;
  };
  const snippet = (text, n = 160) => {
    const flat = text.replace(/\s*\n+\s*/g, " · ");
    return flat.length > n ? flat.slice(0, n - 1) + "…" : flat;
  };

  // ------------------------------------------------------------ text formatting
  function buildCombinedRegex() {
    const parts = [
      "(\\[[^\\]\\n]{1,48}\\])",                 // [PvP value]
      "(↑[^\\s|,;)\\]]+(?:\\s?(?:%|seconds?|x))?)", // ↑enhanced value
    ];
    S.keywords.forEach((k) => parts.push(`(\\b(?:${k.rx})\\b)`));
    S.combined = new RegExp(parts.join("|"), "gi");
  }

  function fmtLine(line) {
    let out = "", last = 0;
    S.combined.lastIndex = 0;
    let m;
    while ((m = S.combined.exec(line))) {
      if (m[0] === "") { S.combined.lastIndex++; continue; }
      out += esc(line.slice(last, m.index));
      if (m[1]) out += `<span class="pvp" title="PvP value">${esc(m[1])}</span>`;
      else if (m[2]) out += `<span class="enh" title="Enhanced / catalyst value">${esc(m[2])}</span>`;
      else {
        const idx = m.slice(3).findIndex((g) => g !== undefined);
        const kw = S.keywords[idx];
        if (kw && (LINK_GROUPS.has(kw.group) || LINK_EXTRA.has(kw.name))) {
          out += `<button type="button" class="kw el-${esc(kw.group)}" data-kw="${esc(kw.name)}" title="Everything about ${esc(kw.name)}">${esc(m[0])}</button>`;
        } else out += esc(m[0]);
      }
      last = m.index + m[0].length;
    }
    return out + esc(line.slice(last));
  }

  function fmt(text) {
    return (text || "").split("\n").map((line) => {
      const body = fmtLine(line);
      return line.trim().endsWith(":") && line.length < 160 ? `<span class="cond">${body}</span>` : body;
    }).join("\n");
  }

  // ------------------------------------------------------------ keyword helpers
  function rolesOf(e) {
    // exotic weapons "produce" their own weapon type, so weapon-type perks light up
    if (e._roles) return e._roles;
    const roles = {};
    for (const [k, v] of Object.entries(e.kw || {})) roles[k] = new Set(v);
    if (e.cat === "exotic-weapon" && e.frame) {
      S.keywords.filter((k) => k.group === "Weapon").forEach((k) => {
        if (new RegExp(`\\b(?:${k.rx})\\b`, "i").test(e.frame)) (roles[k.name] ||= new Set()).add("produce");
      });
    }
    e._roles = roles;
    return roles;
  }
  const makes = (e, k) => rolesOf(e)[k]?.has("produce");
  const uses = (e, k) => rolesOf(e)[k]?.has("use");

  // ------------------------------------------------------------ shared rendering
  function tagsFor(e) {
    const c = CATS[e.cat] || { label: e.cat };
    const bits = [`<span class="tag ${c.exotic ? "tag-exotic" : ""}">${esc(c.label)}</span>`];
    if (e.el) bits.push(`<span class="tag tag-el el-${esc(e.el)}">${esc(e.el)}</span>`);
    if (e.cls) bits.push(`<span class="tag tag-cls cls-${esc(e.cls)}">${esc(e.cls)}</span>`);
    if (e.slot && e.cat === "armor-mod") bits.push(`<span class="tag">${esc(e.slot)}</span>`);
    if (e.slot && e.cat === "exotic-weapon") bits.push(`<span class="tag">${esc(e.slot)} slot</span>`);
    return bits.join("");
  }
  const elClass = (e) => (e.el ? `el-${e.el}` : e.weaponEls?.length ? `el-${e.weaponEls[e.weaponEls.length - 1]}` : "");

  const RATING = { "✔": "Optimal", "▲": "Viable", "!": "Situational", "✖": "Wasted" };
  function endgameHTML(e) {
    const credit = `<p class="eg-credit">From <a href="${esc(sheetUrl("endgame", e.egExotic ? "Exotic Weapons" : e.eg?.[0]?.tab) || "#")}" target="_blank" rel="noopener">Endgame Analysis</a> by ${esc(S.meta.sources.endgame?.author || "TheAegisRelic")}. PvE endgame ratings, not exact values.</p>`;
    if (e.egExotic) {
      const x = e.egExotic;
      const rate = [["Roaming", x.roam], ["Boss DPS", x.dps], ["Challenge", x.challenge], ["Speedrun", x.speed]]
        .filter(([, v]) => v).map(([k, v]) => `<li><span class="muted">${k}</span> <b>${esc(RATING[v] || v)}</b></li>`).join("");
      return `<section class="eg"><h3>Endgame rating ${x.tier ? `<span class="tier tier-${esc(x.tier)}">${esc(x.tier)}</span>` : ""}</h3>
        ${x.summary ? `<p>${esc(x.summary)}</p>` : ""}${rate ? `<ul class="eg-rates">${rate}</ul>` : ""}
        ${x.usage ? `<p class="muted">${esc(x.usage)}</p>` : ""}${credit}</section>`;
    }
    if (!e.eg?.length) return "";
    return `<section class="eg"><h3>Endgame rating ${[...new Set(e.eg.map((n) => n.tier).filter(Boolean))].map((t) => `<span class="tier tier-${esc(t)}">${esc(t)}</span>`).join(" ")}</h3>
      ${e.eg.map((n) => `<dl class="kv">
        ${e.eg.length > 1 && n.pieces ? `<dt>Piece</dt><dd>${esc(n.pieces)}-piece</dd>` : ""}
        ${n.trigger ? `<dt>Trigger</dt><dd>${esc(n.trigger)}</dd>` : ""}
        ${n.effect ? `<dt>Effect</dt><dd>${esc(n.effect)}</dd>` : ""}
        ${n.tags?.length ? `<dt>Tags</dt><dd>${esc(n.tags.join(", "))}</dd>` : ""}
        ${n.notable ? `<dt>Notable on</dt><dd>${esc(n.notable)}</dd>` : ""}
        ${n.analysis ? `<dt>Notes</dt><dd>${esc(n.analysis)}</dd>` : ""}
      </dl>`).join("")}${credit}</section>`;
  }

  function detailHTML(e) {
    const c = CATS[e.cat] || {};
    const kv = [];
    if (e.perk) kv.push(["Exotic perk", e.perk]);
    if (e.frame) kv.push(["Frame", e.frame]);
    if (e.perks?.length) kv.push(["Perks", e.perks.join("\n")]);
    if (e.source) kv.push(["Source", e.source]);
    if (e.artifact) kv.push(["Artifact", `${e.artifact}${e.column ? ` · column ${e.column}` : ""}`]);
    if (e.tags) kv.push(["Artifact focus", e.tags]);
    if (e.cost) kv.push(["Cost", e.cost]);
    if (e.slot && e.cat === "armor-mod") kv.push(["Armor slot", e.slot]);
    if (e.group) kv.push(["Group", e.group]);
    if (e.column && e.cat === "exotic-class") kv.push(["Column", e.column]);
    if (e.stats) kv.push(["Stat changes", e.stats]);
    if (e.note) kv.push(["Notes", e.note]);
    if (e.mods?.length) kv.push(["Modified by", e.mods.join(", ")]);

    const body = e.pieces?.length
      ? e.pieces.map((p) => `<div class="piece"><h4>${esc(p.count)} · ${esc(p.name)}</h4><div class="desc">${fmt(p.desc)}</div></div>`).join("")
      : `<div class="desc">${fmt(e.desc)}</div>`;

    const roles = rolesOf(e);
    const kwChips = Object.entries(roles)
      .filter(([, r]) => r.has("produce") || r.has("use"))
      .map(([k, r]) => {
        const g = S.kwByName.get(k)?.group || "General";
        const role = [r.has("produce") && "makes", r.has("use") && "uses"].filter(Boolean).join(" + ");
        return `<button type="button" class="chip el-${esc(g)}" data-kw="${esc(k)}"><span class="dot"></span>${esc(k)} <span class="role">${role}</span></button>`;
      }).join("");

    const egHTML = (e.cat === "verb" ? "" : glossaryBoxHTML([e.desc, ...(e.pieces || []).map((x) => x.desc)], [], "Keywords explained")) + endgameHTML(e);

    const src = sheetUrl("compendium", e.sheet);
    return `
      <button type="button" class="btn btn-quiet back-to-list" data-back>‹ Back to results</button>
      <h2 class="${c.exotic ? "exotic" : ""}"><a class="plain-link" href="${itemHref(e)}">${esc(e.name)}</a></h2>
      <div class="detail-meta">${tagsFor(e)}</div>
      <p><a class="btn btn-primary" href="${itemHref(e)}">Open full page</a></p>
      ${body}
      ${kv.length ? `<section><dl class="kv">${kv.map(([k, v]) => `<dt>${esc(k)}</dt><dd>${fmt(v)}</dd>`).join("")}</dl></section>` : ""}
      ${egHTML}
      ${kwChips ? `<section><h3>Keywords</h3><p class="muted" style="margin:0 0 8px;font-size:.9rem">Select one to list everything else that makes or uses it.</p><div class="kwlist">${kwChips}</div></section>` : ""}
      <div class="detail-actions">
        ${src ? `<a class="btn" href="${esc(src)}" target="_blank" rel="noopener">Open in the Compendium (${esc(e.sheet)})</a>` : ""}
      </div>
      <p class="legend" style="margin-top:14px"><span class="pvp">[bracketed] = PvP value</span><span class="enh">↑ = enhanced or catalyst value</span><span>? = not yet tested</span></p>`;
  }

  // ------------------------------------------------------------ explore
  function searchEntries({ q, cats, el, cls, kw, role }) {
    const terms = q.toLowerCase().split(/\s+/).filter(Boolean);
    const out = [];
    for (const e of S.entries) {
      if (cats.size && !cats.has(e.cat)) continue;
      if (el && e.el !== el && !(e.weaponEls || []).includes(el)) continue;
      if (cls && e.cls && e.cls !== cls) continue;
      if (cls && !e.cls && ["super", "aspect", "melee", "exotic-armor", "class-ability"].includes(e.cat)) continue;
      if (kw) {
        const r = rolesOf(e)[kw];
        if (!r) continue;
        if (role === "makes" && !r.has("produce")) continue;
        if (role === "uses" && !r.has("use")) continue;
      }
      let score = 0;
      if (terms.length) {
        const name = e.name.toLowerCase();
        const hay = e._hay ||= (e.name + " " + e.desc + " " + (e.perk || "") + " " + (e.perks || []).join(" ") + " " + (e.source || "") + " " + (e.artifact || "")).toLowerCase();
        let ok = true;
        for (const t of terms) {
          if (name === t) score += 50;
          else if (name.startsWith(t)) score += 20;
          else if (name.includes(t)) score += 10;
          else if (hay.includes(t)) score += 1;
          else { ok = false; break; }
        }
        if (!ok) continue;
      }
      out.push({ e, score });
    }
    if (terms.length) out.sort((a, b) => b.score - a.score || a.e.name.localeCompare(b.e.name));
    else out.sort((a, b) => a.e.name.localeCompare(b.e.name));
    return out.map((x) => x.e);
  }

  function readExploreParams() {
    const { q } = parseHash();
    return {
      q: q.get("q") || "",
      cats: new Set((q.get("cat") || "").split(",").filter(Boolean)),
      el: q.get("el") || "",
      cls: q.get("cls") || "",
      kw: q.get("kw") || "",
      role: q.get("role") || "",
      id: q.get("id") || "",
      more: +(q.get("more") || 0),
    };
  }

  function exploreHash(p) {
    const q = new URLSearchParams();
    if (p.q) q.set("q", p.q);
    if (p.cats.size) q.set("cat", [...p.cats].join(","));
    if (p.el) q.set("el", p.el);
    if (p.cls) q.set("cls", p.cls);
    if (p.kw) q.set("kw", p.kw);
    if (p.role) q.set("role", p.role);
    if (p.id) q.set("id", p.id);
    const s = q.toString();
    return "#/explore" + (s ? "?" + s : "");
  }

  function renderExplore() {
    const p = readExploreParams();
    const groups = {};
    Object.entries(CATS).forEach(([k, v]) => (groups[v.group] ||= []).push([k, v]));
    const counts = {};
    S.entries.forEach((e) => { counts[e.cat] = (counts[e.cat] || 0) + 1; });

    // keep the search box (and its focus) between keystrokes
    let shell = app.querySelector(".explore");
    if (!shell) {
      app.innerHTML = `
      <div class="explore">
        <aside class="filters" aria-label="Filters">
          <label class="visually-hidden" for="q">Search</label>
          <input id="q" class="input" type="search" placeholder="Search perks, exotics, mods…" autocomplete="off">
          <details ${window.matchMedia("(max-width: 720px)").matches ? "" : "open"}><summary>Filters</summary><div class="filter-body"></div></details>
        </aside>
        <div class="list-col">
          <div class="results-head"><h2 id="count"></h2><button type="button" class="btn btn-quiet" data-clear>Clear filters</button></div>
          <div class="wstrip" data-wstrip hidden></div>
          <ul class="results" role="list"></ul>
        </div>
        <article class="detail" aria-live="polite"></article>
      </div>`;
      shell = app.querySelector(".explore");
      const input = shell.querySelector("#q");
      let t;
      input.addEventListener("input", () => {
        clearTimeout(t);
        t = setTimeout(() => { const cur = readExploreParams(); cur.q = input.value; cur.id = ""; go(exploreHash(cur), true); }, 140);
      });
    }
    const input = shell.querySelector("#q");
    if (document.activeElement !== input) input.value = p.q;

    const kwOptions = S.keywords.map((k) => `<option value="${esc(k.name)}" ${p.kw === k.name ? "selected" : ""}>${esc(k.name)} (${esc(k.group)})</option>`).join("");
    shell.querySelector(".filter-body").innerHTML = `
      <div class="filter-group"><h3>Element</h3><div class="chips">${ELEMENTS.map((el) => `<button type="button" class="chip el-${el}" aria-pressed="${p.el === el}" data-f="el" data-v="${el}"><span class="dot"></span>${el}</button>`).join("")}</div></div>
      <div class="filter-group"><h3>Class</h3><div class="chips">${CLASSES.map((c) => `<button type="button" class="chip" aria-pressed="${p.cls === c}" data-f="cls" data-v="${c}">${c}</button>`).join("")}</div></div>
      <div class="filter-group"><h3>Keyword</h3>
        <select class="input" data-kwsel><option value="">Any keyword</option>${kwOptions}</select>
        ${p.kw ? `<div class="chips" style="margin-top:6px">${["", "makes", "uses"].map((r) => `<button type="button" class="chip" aria-pressed="${p.role === r}" data-f="role" data-v="${r}">${r ? (r === "makes" ? "Makes it" : "Uses it") : "Either"}</button>`).join("")}</div>` : ""}
      </div>
      ${Object.entries(groups).map(([g, list]) => `
        <div class="filter-group"><h3>${esc(g)}</h3><div class="chips">${list.map(([k, v]) => `<button type="button" class="chip" aria-pressed="${p.cats.has(k)}" data-f="cat" data-v="${k}">${esc(v.label)} <span class="muted">${counts[k] || 0}</span></button>`).join("")}</div></div>`).join("")}`;

    const results = searchEntries(p);
    const limit = 120 + p.more * 200;
    const kwNote = p.kw ? ` that ${p.role === "makes" ? "make" : p.role === "uses" ? "use" : "mention"} ${p.kw}` : "";
    shell.querySelector("#count").textContent = `${results.length.toLocaleString()} result${results.length === 1 ? "" : "s"}${kwNote}`;
    const list = shell.querySelector(".results");
    // weapons live in their own file; show name matches above the Compendium results
    const strip = shell.querySelector("[data-wstrip]");
    if (p.q.trim().length >= 2) {
      ensureWeapons().then(() => {
        const t = p.q.toLowerCase().trim();
        const hits = S.weapons.weapons.filter((w) => w.n.toLowerCase().includes(t)).slice(0, 8);
        if (readExploreParams().q !== p.q) return;
        strip.hidden = !hits.length;
        strip.innerHTML = hits.length ? `<span class="muted">Weapons:</span> ${hits.map((w) => `<a class="perk" href="#/weapon/${w.slug}" ${w.tier === "Exotic" ? 'style="color:var(--exotic)"' : ""}>${esc(w.n)}</a>`).join("")}` : "";
      });
    } else strip.hidden = true;
    list.innerHTML = results.slice(0, limit).map((e) => `
      <li><button type="button" class="result ${elClass(e)}" data-open="${esc(e.id)}" aria-current="${p.id === e.id}">
        <span class="result-top"><span class="result-name ${CATS[e.cat]?.exotic ? "exotic" : ""}">${esc(e.name)}</span>${tagsFor(e)}</span>
        <span class="result-snip">${esc(snippet(e.desc))}</span>
      </button></li>`).join("") +
      (results.length > limit ? `<li><button type="button" class="btn" data-more style="width:100%;margin-top:6px">Show ${Math.min(200, results.length - limit)} more</button></li>` : "") +
      (!results.length ? `<li class="muted" style="padding:12px 0">Nothing matches. Try fewer words, or clear a filter.</li>` : "");

    const detail = shell.querySelector(".detail");
    const sel = p.id && S.byId.get(p.id);
    shell.classList.toggle("has-detail", !!sel);
    detail.innerHTML = sel ? detailHTML(sel) : explainer();
    if (sel && window.matchMedia("(max-width: 720px)").matches) window.scrollTo(0, 0);

    shell.onclick = (ev) => {
      const t = ev.target.closest("button, a");
      if (!t) return;
      const cur = readExploreParams();
      if (t.dataset.f) {
        const { f, v } = t.dataset;
        if (f === "cat") { cur.cats.has(v) ? cur.cats.delete(v) : cur.cats.add(v); }
        else cur[f] = cur[f] === v ? "" : v;
        cur.id = "";
        go(exploreHash(cur), true);
      } else if (t.dataset.open) {
        cur.id = t.dataset.open; go(exploreHash(cur));
      } else if (t.dataset.kw) {
        go(exploreHash({ q: "", cats: new Set(), el: "", cls: cur.cls, kw: t.dataset.kw, role: "", id: glossaryFor(t.dataset.kw)?.id || "" }));
      } else if (t.dataset.clear !== undefined) {
        go("#/explore");
      } else if (t.dataset.more !== undefined) {
        const extra = shell.querySelectorAll(".result").length;
        list.lastElementChild.remove();
        list.insertAdjacentHTML("beforeend", results.slice(extra, extra + 200).map((e) => `
          <li><button type="button" class="result ${elClass(e)}" data-open="${esc(e.id)}"><span class="result-top"><span class="result-name ${CATS[e.cat]?.exotic ? "exotic" : ""}">${esc(e.name)}</span>${tagsFor(e)}</span><span class="result-snip">${esc(snippet(e.desc))}</span></button></li>`).join("") +
          (results.length > extra + 200 ? `<li><button type="button" class="btn" data-more style="width:100%;margin-top:6px">Show more</button></li>` : ""));
      } else if (t.dataset.back !== undefined) {
        cur.id = ""; go(exploreHash(cur));
      }
    };
    shell.querySelector("[data-kwsel]").onchange = (ev) => {
      const cur = readExploreParams(); cur.kw = ev.target.value; cur.role = ""; cur.id = ""; go(exploreHash(cur), true);
    };
  }


  // ------------------------------------------------------------ keyword glossary boxes
  // keyword -> glossary entries to explain it (by entry name in the subclass "Glossary" sections).
  // Some keywords pull in the follow-on effect too, e.g. Scorch builds to Ignition.
  const GLOSSARY_LINKS = {
    "Jolt": ["Jolted"], "Void Overshield": ["Overshield"], "Volatile": ["Volatile", "Volatile Rounds"],
    "Unravel": ["Unravel", "Unraveling Rounds"], "Scorch": ["Scorch", "Ignition"], "Slow": ["Slow", "Freeze"],
    "Freeze": ["Freeze", "Shatter"], "Tangle": ["Tangle"], "Elemental Buff": ["Elemental Effects"], "Elemental Debuff": ["Elemental Effects"],
  };
  function glossaryEntries(kw) {
    const verbs = S.entries.filter((e) => e.cat === "verb");
    const names = GLOSSARY_LINKS[kw];
    if (names) return names.map((n) => verbs.find((v) => v.name === n)).filter(Boolean);
    const k = S.kwByName.get(kw);
    if (!k) return [];
    const rx = new RegExp(`^(?:${k.rx})$`, "i");
    return verbs.filter((v) => rx.test(v.name.trim()));
  }
  // which glossary entries a block of text calls for, in the order they first appear
  function glossaryFor(textOrKw, skipIds = []) {
    if (S.kwByName.has(textOrKw)) return glossaryEntries(textOrKw)[0];
    const text = textOrKw || "";
    const found = [];
    for (const k of S.keywords) {
      const m = new RegExp(`\\b(?:${k.rx})\\b`, "i").exec(text);
      if (m) found.push([m.index, k.name]);
    }
    found.sort((a, b) => a[0] - b[0]);
    const out = [];
    found.forEach(([, name]) => glossaryEntries(name).forEach((v) => { if (!out.includes(v) && !skipIds.includes(v.id)) out.push(v); }));
    return out;
  }
  function glossaryBoxHTML(texts, skipIds = [], title = "Keywords in this perk") {
    const list = glossaryFor(texts.filter(Boolean).join("\n"), skipIds);
    if (!list.length) return "";
    return `<section class="gloss" aria-label="${esc(title)}">
      <h4>${esc(title)}</h4>
      ${list.map((v) => `<article class="gloss-item el-${esc(v.el)}">
        <h5><a href="${itemHref(v)}">${esc(v.name)}</a> <span class="tag tag-el">${esc(v.el)}</span></h5>
        <div class="desc">${fmt(v.desc)}</div>
      </article>`).join("")}
    </section>`;
  }


  function explainer() {
    const n = S.entries.length.toLocaleString();
    return `
      <h2>Look anything up</h2>
      <p>${n} perks, abilities, exotics, mods and mechanics from the Destiny Data Compendium, in one searchable list. Filter by keyword to find everything that makes or uses an effect.</p>
      <p>Pick something to see its exact values and, where Endgame Analysis covers it, its endgame rating. Underlined words like <button type="button" class="kw el-Arc" data-kw="Jolt" style="color:var(--arc);background:none;border:0;padding:0;text-decoration:underline dotted;cursor:pointer;font:inherit">Jolt</button> or <button type="button" class="kw el-Solar" data-kw="Scorch" style="color:var(--solar);background:none;border:0;padding:0;text-decoration:underline dotted;cursor:pointer;font:inherit">Scorch</button> jump to everything that makes or uses that effect.</p>
      <p class="legend"><span class="pvp">[bracketed] = PvP value</span><span class="enh">↑ = enhanced or catalyst value</span><span>? = not yet tested</span></p>
      <p>Every entry also has its own page with sources and related entries.</p>`;
  }

  // ------------------------------------------------------------ boss data
  const BOSS_TABS = [
    ["health", "Boss health"], ["bosses", "Boss notes"], ["weapons", "Weapon damage"],
    ["abilities", "Ability damage"], ["sustained", "Sustained DPS"], ["swap", "Swap DPS"], ["encounters", "Encounter breakdowns"],
  ];
  const isNum = (v) => /^-?[\d,]*\.?\d+%?$/.test(v.trim());
  const toNum = (v) => parseFloat(v.replace(/[,%]/g, ""));

  async function renderBoss(which) {
    which = which || "health";
    if (!S.tables) {
      app.innerHTML = `<p class="loading">Loading boss tables…</p>`;
      S.tables = await (await fetch("data/tables.json")).json();
    }
    await Promise.all([ensureWeapons(), ensureIcons()]);
    const tabs = BOSS_TABS.map(([k, label]) => `<a href="#/boss/${k}" ${k === which ? 'aria-current="page"' : ""}>${label}</a>`).join("");
    const src = (k) => S.meta.sources[k];
    if (which === "encounters") return renderEncounters(tabs);
    const t = S.tables[which];
    if (!t) { app.innerHTML = `<p>That table isn't in the data. <a href="#/boss">Back to boss data</a></p>`; return; }
    const s = src(t.source);
    app.innerHTML = `
      <h1>Boss data</h1>
      <p class="intro">Testing by ${esc(s.author)}. Values are copied as published; open the original for formulas, charts and context.</p>
      <nav class="tabbar" aria-label="Boss tables">${tabs}</nav>
      <div class="table-tools">
        <input class="input" type="search" placeholder="Filter rows…" data-tfilter aria-label="Filter rows">
        <span class="muted" data-tcount></span>
        <a href="${esc(sheetUrl(t.source, t.tab))}" target="_blank" rel="noopener">Open “${esc(t.tab)}” in ${esc(s.title)}</a>
      </div>
      <div class="tablewrap" data-twrap></div>`;
    mountTable(app.querySelector("[data-twrap]"), t, app.querySelector("[data-tfilter]"), app.querySelector("[data-tcount]"), { cell: bossCell(which) });
  }

  // which column gets a picture in each boss table
  function bossCell(which) {
    const withPic = (pic, v) => (pic ? `<span class="cellpic">${pic}<span>${esc(v)}</span></span>` : esc(v));
    if (which === "health" || which === "bosses") return (v, i) => (i === 1 ? withPic(activityPic(v), v) : esc(v));
    if (which === "weapons") return (v, i, r) => {
      if (i !== 1) return esc(v);
      const named = S.weaponByKey.get(normName(v));
      if (named?.icon) return withPic(weaponThumb(named, 32), v);
      const g = genericWeapon(r[0], v);
      return withPic(g ? `<span class="thumb-generic" title="Example: ${esc(g.n)}">${weaponThumb(g, 32)}</span>` : "", v);
    };
    if (which === "abilities") return (v, i) => (i === 1 ? withPic(picFor(v, /^Glaive - /.test(v) ? "" : "ability"), v) : esc(v));
    if (which === "sustained" || which === "swap") return (v, i) => (i === 0 ? withPic(picFor(v), v) : esc(v));
    return undefined;
  }

  function mountTable(wrap, t, filterInput, countEl, opts = {}) {
    let sortCol = opts.sortDefault ?? -1, dir = 1;
    const numericCols = t.columns.map((_, i) => {
      const vals = t.rows.map((r) => r[i]).filter((v) => v && v !== "/" && v !== "N/A");
      return vals.length > 0 && vals.filter(isNum).length / vals.length > 0.7;
    });
    const draw = () => {
      const f = (filterInput?.value || "").toLowerCase().trim();
      let rows = f ? t.rows.filter((r) => r.join(" ").toLowerCase().includes(f)) : t.rows.slice();
      if (sortCol >= 0) {
        rows.sort((a, b) => {
          const x = a[sortCol] || "", y = b[sortCol] || "";
          if (sortCol === opts.tierCol) return (tierRank(x) - tierRank(y)) * dir;
          if (numericCols[sortCol]) {
            const nx = isNum(x) ? toNum(x) : -Infinity, ny = isNum(y) ? toNum(y) : -Infinity;
            return (nx - ny) * dir;
          }
          return x.localeCompare(y) * dir;
        });
      }
      if (countEl) countEl.textContent = `${rows.length} of ${t.rows.length} rows`;
      wrap.innerHTML = `<table class="data"><thead><tr>${t.columns.map((c, i) => `<th scope="col" ${i === sortCol ? `aria-sort="${dir > 0 ? "ascending" : "descending"}"` : ""}><button type="button" data-sort="${i}">${esc(c)}</button></th>`).join("")}</tr></thead>
        <tbody>${rows.map((r) => `<tr>${t.columns.map((_, i) => {
          const v = r[i] || "";
          const cls = numericCols[i] && isNum(v) ? "num" : v.length > 40 ? "wrap" : "";
          return `<td class="${cls}">${opts.cell ? opts.cell(v, i, r) : esc(v)}</td>`;
        }).join("")}</tr>`).join("")}</tbody></table>`;
    };
    wrap.onclick = (ev) => {
      const b = ev.target.closest("[data-sort]");
      if (!b) return;
      const i = +b.dataset.sort;
      if (sortCol === i) dir = -dir; else { sortCol = i; dir = numericCols[i] ? -1 : 1; }
      draw();
    };
    if (filterInput) filterInput.oninput = draw;
    draw();
  }

  function renderEncounters(tabs) {
    const enc = S.tables.encounters;
    const names = Object.keys(enc);
    const { q } = parseHash();
    const pick = q.get("e") && enc[q.get("e")] ? q.get("e") : names[0];
    app.innerHTML = `
      <h1>Boss data</h1>
      <p class="intro">How each boss's health bar was measured: damage dealt per hit against the percentage of health removed. From ${esc(S.meta.sources.bosshealth.author)}'s Boss Health sheet.</p>
      <nav class="tabbar" aria-label="Boss tables">${tabs}</nav>
      <div class="table-tools">
        <label for="encsel" class="visually-hidden">Encounter</label>
        <select id="encsel" class="input" style="max-width:340px">${names.map((n) => `<option ${n === pick ? "selected" : ""}>${esc(n)}</option>`).join("")}</select>
        <a href="${esc(sheetUrl("bosshealth", pick))}" target="_blank" rel="noopener">Open this tab in the original</a>
      </div>
      ${(() => { const a = encounterActivity(pick); const pic = a && activityPic(a, "lg"); return pic ? `<figure class="act-banner">${pic}<figcaption>${esc(a)}</figcaption></figure>` : ""; })()}
      <div class="tablewrap" data-twrap></div>`;
    mountTable(app.querySelector("[data-twrap]"), enc[pick], null, null, {
      cell: (v, i) => { if (i !== 0) return esc(v); const pic = picFor(v.replace(/\s+\d+$/, "")); return pic ? `<span class="cellpic">${pic}<span>${esc(v)}</span></span>` : esc(v); },
    });
    app.querySelector("#encsel").onchange = (ev) => go(`#/boss/encounters?e=${encodeURIComponent(ev.target.value)}`, true);
  }

  // ------------------------------------------------------------ wiki: shared
  const BNET = "https://www.bungie.net";
  const TIER_ORDER = ["S", "A", "B", "C", "D", "E", "F"];
  const tierRank = (t) => { const i = TIER_ORDER.indexOf((t || "").trim()); return i < 0 ? 99 : i; };
  const normName = (t) => (t || "").normalize("NFKD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/^the /, "").replace(/[^a-z0-9]+/g, "");
  const slugify = (t) => (t || "").toLowerCase().normalize("NFKD").replace(/[̀-ͯ]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  const itemHref = (e) => `#/item/${encodeURIComponent(e.id)}`;
  const tierBadge = (t, title) => (t ? `<span class="tier tier-${esc(t)}" title="${esc(title || `Tier ${t}`)}">${esc(t)}</span>` : "");
  const crumbs = (list) => `<nav class="crumbs" aria-label="Breadcrumb">${list.map(([label, href]) => (href ? `<a href="${href}">${esc(label)}</a>` : `<span aria-current="page">${esc(label)}</span>`)).join('<span class="sep">›</span>')}</nav>`;

  // category pages: how each kind of entry is grouped
  const WIKI = {
    "exotic-armor": { title: "Exotic armor", group: (e) => e.cls || "Any class", order: CLASSES },
    "exotic-class": { title: "Exotic class item perks", group: (e) => `${e.cls || "Any class"} · ${e.column || ""} column`, order: [] },
    "aspect": { title: "Aspects", group: (e) => `${e.el} ${e.cls}`, order: [] },
    "fragment": { title: "Fragments", group: (e) => e.el, order: ELEMENTS },
    "super": { title: "Supers", group: (e) => `${e.el} ${e.cls}`, order: [] },
    "grenade": { title: "Grenades", group: (e) => e.el + (e.el === "Prismatic" ? ` ${e.cls}` : ""), order: ELEMENTS },
    "melee": { title: "Melees", group: (e) => `${e.el} ${e.cls}`, order: [] },
    "class-ability": { title: "Class abilities", group: (e) => e.cls, order: CLASSES },
    "class-trait": { title: "Class traits", group: (e) => e.cls, order: CLASSES },
    "verb": { title: "Keywords", group: (e) => e.el, order: ELEMENTS },
    "armor-set": { title: "Armor set bonuses", group: (e) => e.name[0].toUpperCase(), order: [] },
    "armor-mod": { title: "Armor mods", group: (e) => [e.slot, e.group].filter(Boolean).join(" · "), order: ["Helmet", "Arms", "Chest", "Legs", "Class Item"] },
    "weapon-trait": { title: "Weapon traits", group: (e) => e.name[0].toUpperCase(), order: [] },
    "origin-trait": { title: "Origin traits", group: (e) => e.name[0].toUpperCase(), order: [] },
    "intrinsic": { title: "Weapon frames", group: () => "Frames", order: [] },
    "weapon-mod": { title: "Weapon mods", group: () => "Mods", order: [] },
    "weapon-info": { title: "Weapon info", group: (e) => e.group || "Info", order: [] },
    "mechanic": { title: "Activity modifiers", group: (e) => e.group || "Other", order: [] },
    "exotic-weapon": { title: "Exotic weapons (Compendium notes)", group: (e) => `${e.slot || ""} slot`, order: [] },
  };

  async function ensureWeapons() {
    if (!S.weapons) S.weapons = await (await fetch("data/weapons.json")).json();
    if (!S.weaponByKey) {
      S.weaponByKey = new Map();
      S.weaponBySlug = new Map();
      S.weapons.weapons.forEach((w) => { S.weaponByKey.set(normName(w.n), w); S.weaponBySlug.set(w.slug, w); });
      // which weapons can roll which perk (by name, enhanced folded in)
      S.rollers = new Map();
      S.weapons.weapons.forEach((w) => w.cols.forEach((c) => c.perks.forEach((h) => {
        const k = normName(S.weapons.perks[h]?.n);
        if (!k) return;
        if (!S.rollers.has(k)) S.rollers.set(k, new Set());
        S.rollers.get(k).add(w);
      })));
    }
    return S.weapons;
  }

  // compendium entry for a weapon perk, if the Compendium documents it
  let perkIndex = null;
  function compendiumPerk(name) {
    if (!perkIndex) {
      perkIndex = new Map();
      S.entries.filter((e) => ["weapon-trait", "origin-trait", "intrinsic", "weapon-mod", "exotic-weapon"].includes(e.cat))
        .forEach((e) => { if (!perkIndex.has(normName(e.name))) perkIndex.set(normName(e.name), e); });
    }
    return perkIndex.get(normName((name || "").replace(/^↑/, "")));
  }

  // ------------------------------------------------------------ home
  const HOME = [
    { title: "Exotics", items: [
      { label: "Exotic weapons", href: "#/weapons?rarity=Exotic", count: () => S.meta.counts?.exotics, blurb: "Perks, catalysts and endgame ratings", exotic: true },
      { label: "Exotic armor", cat: "exotic-armor", blurb: "Every exotic perk, by class", exotic: true },
      { label: "Exotic class items", cat: "exotic-class", blurb: "Spirit perks for both columns", exotic: true },
    ] },
    { title: "Subclasses", items: [
      { label: "Aspects", cat: "aspect", blurb: "With fragment slots" },
      { label: "Fragments", cat: "fragment", blurb: "With stat changes" },
      { label: "Supers", cat: "super" },
      { label: "Grenades", cat: "grenade" },
      { label: "Melees", cat: "melee" },
      { label: "Class abilities", cat: "class-ability", blurb: "Cooldowns and chunk scalars" },
      { label: "Keywords", cat: "verb", blurb: "Jolt, Scorch, Devour and the rest" },
    ] },
    { title: "Weapons and armor", items: [
      { label: "Legendary weapons", href: "#/weapons?rarity=Legendary", count: () => S.meta.counts?.legendaries, blurb: "Every perk they can roll, plus the best picks" },
      { label: "Weapon traits", cat: "weapon-trait" },
      { label: "Origin traits", cat: "origin-trait" },
      { label: "Weapon frames", cat: "intrinsic" },
      { label: "Armor set bonuses", href: "#/armor", count: () => S.entries.filter((e) => e.cat === "armor-set").length, blurb: "2- and 4-piece bonuses with Endgame notes" },
      { label: "Armor mods & stats", href: "#/armor/mods", count: () => S.entries.filter((e) => e.cat === "armor-mod").length, blurb: "Every mod, plus what each armor stat does" },
      { label: "Artifacts", href: "#/wiki/artifacts", count: () => artifacts().length, blurb: "Every seasonal artifact and its perks" },
    ] },
    { title: "Endgame", items: [
      { label: "Boss health", href: "#/boss/health", blurb: "Health at every power delta" },
      { label: "Boss damage", href: "#/boss/weapons", blurb: "Weapon and ability damage tests" },
      { label: "Sustained DPS", href: "#/boss/sustained" },
      { label: "Buff stacking", href: "#/stacking", blurb: "Which damage buffs stack, and by how much" },
      { label: "Activity modifiers", cat: "mechanic" },
      { label: "Archetypes", href: "#/archetypes", blurb: "Frame testing and every weapon ranked by type" },
    ] },
  ];

  function renderHome() {
    const counts = {};
    S.entries.forEach((e) => { counts[e.cat] = (counts[e.cat] || 0) + 1; });
    app.innerHTML = `
      <section class="home-hero">
        <h1>Destiny 2, by the numbers</h1>
        <p>Exact values for perks, abilities and exotics, every weapon's perk pool with the community's best picks, and boss data, gathered from the community's testing spreadsheets and Bungie's own item data.</p>
        <form class="home-search" role="search">
          <label class="visually-hidden" for="homeq">Search everything</label>
          <input id="homeq" class="input" type="search" placeholder="Search a perk, exotic, aspect, weapon…" autocomplete="off">
          <button class="btn btn-primary" type="submit">Search</button>
        </form>
      </section>
      ${HOME.map((g) => `
        <section class="home-group" aria-labelledby="hg-${slugify(g.title)}">
          <h2 id="hg-${slugify(g.title)}">${esc(g.title)}</h2>
          <div class="home-grid">${g.items.map((it) => {
            const href = it.href || `#/wiki/${it.cat}`;
            const n = it.cat ? counts[it.cat] : it.count?.();
            return `<a class="home-tile ${it.exotic ? "exotic" : ""}" href="${href}">
              <span class="ht-label">${esc(it.label)}</span>
              ${n ? `<span class="ht-count">${n.toLocaleString()}</span>` : ""}
              ${it.blurb ? `<span class="ht-blurb">${esc(it.blurb)}</span>` : ""}
            </a>`;
          }).join("")}</div>
        </section>`).join("")}`;
    app.querySelector(".home-search").onsubmit = (ev) => {
      ev.preventDefault();
      const v = app.querySelector("#homeq").value.trim();
      go(`#/explore${v ? `?q=${encodeURIComponent(v)}` : ""}`);
    };
  }

  // ------------------------------------------------------------ wiki: category pages
  function renderCategory(cat) {
    if (cat === "artifacts" || cat === "artifact-perk") return renderArtifacts();
    const conf = WIKI[cat];
    if (!conf) { app.innerHTML = `<p>No such section. <a href="#/">Back home</a></p>`; return; }
    const list = S.entries.filter((e) => e.cat === cat).sort((a, b) => a.name.localeCompare(b.name));
    const groups = new Map();
    list.forEach((e) => { const g = conf.group(e) || "Other"; (groups.get(g) || groups.set(g, []).get(g)).push(e); });
    const keys = [...groups.keys()].sort((a, b) => {
      const ia = conf.order.findIndex((o) => a.startsWith(o)), ib = conf.order.findIndex((o) => b.startsWith(o));
      return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib) || a.localeCompare(b);
    });
    app.innerHTML = `
      ${crumbs([["Home", "#/"], [conf.title]])}
      <div class="cat-head"><h1>${esc(conf.title)}</h1>
        <input class="input" type="search" placeholder="Filter ${list.length} ${esc(conf.title.toLowerCase())}…" data-cfilter aria-label="Filter this list"></div>
      ${keys.map((g) => `
        <section class="cat-group" data-group>
          <h2>${esc(g)}</h2>
          <ul class="cat-list">${groups.get(g).map((e) => `
            <li data-name="${esc((e.name + " " + e.desc).toLowerCase())}"><a class="cat-item ${elClass(e)} ${CATS[e.cat]?.exotic ? "exotic" : ""}" href="${itemHref(e)}">
              <span class="ci-name">${esc(e.name)}${e.eg?.[0]?.tier ? ` ${tierBadge(e.eg[0].tier, "Endgame Analysis tier")}` : ""}</span>
              ${e.perk ? `<span class="ci-sub">${esc(e.perk)}</span>` : ""}
              <span class="ci-snip">${esc(snippet(e.desc, 120))}</span></a></li>`).join("")}</ul>
        </section>`).join("")}`;
    const f = app.querySelector("[data-cfilter]");
    f.oninput = () => {
      const v = f.value.toLowerCase().trim();
      app.querySelectorAll("[data-group]").forEach((sec) => {
        let shown = 0;
        sec.querySelectorAll("li").forEach((li) => { const hit = !v || li.dataset.name.includes(v); li.hidden = !hit; shown += hit; });
        sec.hidden = !shown;
      });
    };
  }

  // ------------------------------------------------------------ wiki: artifacts
  function artifacts() {
    if (S._artifacts) return S._artifacts;
    const map = new Map();
    S.entries.filter((e) => e.cat === "artifact-perk").forEach((e) => {
      if (!map.has(e.artifact)) map.set(e.artifact, { name: e.artifact, slug: slugify(e.artifact), tags: e.tags, perks: [] });
      map.get(e.artifact).perks.push(e);
    });
    S._artifacts = [...map.values()];
    return S._artifacts;
  }

  function renderArtifacts() {
    const list = artifacts();
    app.innerHTML = `
      ${crumbs([["Home", "#/"], ["Artifacts"]])}
      <h1>Artifacts</h1>
      <p class="intro">Seasonal artifacts and their perks, newest first, as listed in the Compendium. Artifact perks are disabled in Competitive and Trials.</p>
      <div class="home-grid" style="margin-top:16px">${list.map((a) => {
        const [name, season] = splitArtifact(a.name);
        return `<a class="home-tile" href="#/artifact/${a.slug}"><span class="ht-label">${esc(name)}</span><span class="ht-count">${a.perks.length} perks</span>
        <span class="ht-blurb">${esc(season ? `${season}` : "")}${a.tags ? `${season ? " · " : ""}${esc(a.tags.replace(/\s*⯁\s*/g, " · "))}` : ""}</span></a>`;
      }).join("")}</div>`;
  }
  const splitArtifact = (n) => { const m = (n || "").match(/^(.*?)\s*\(([^)]+)\)\s*$/); return m ? [m[1], m[2]] : [n, ""]; };

  function renderArtifact(slug) {
    const a = artifacts().find((x) => x.slug === slug);
    if (!a) { app.innerHTML = `<p>Artifact not found. <a href="#/wiki/artifacts">All artifacts</a></p>`; return; }
    const [name, season] = splitArtifact(a.name);
    const cols = [1, 2, 3].map((c) => a.perks.filter((p) => p.column === c));
    app.innerHTML = `
      ${crumbs([["Home", "#/"], ["Artifacts", "#/wiki/artifacts"], [name]])}
      <h1>${esc(name)}</h1>
      <p class="intro">${season ? `${esc(season)}. ` : ""}${a.tags ? `Focus: ${esc(a.tags.replace(/\s*⯁\s*/g, " · "))}` : ""}</p>
      <div class="artifact-grid">${cols.map((list, i) => `
        <section class="artifact-col" aria-label="Column ${i + 1}">
          <h2>Column ${i + 1} <span class="muted" aria-hidden="true">${"⯁".repeat(i + 1)}</span></h2>
          ${list.map((p) => `<article class="perk-card">
            <h3><a href="${itemHref(p)}">${esc(p.name)}</a> ${tierBadge(p.eg?.[0]?.tier, "Endgame Analysis tier")}</h3>
            <div class="desc">${fmt(p.desc)}</div>
            ${p.eg?.[0]?.analysis ? `<p class="muted pc-note">${esc(p.eg[0].analysis)}</p>` : ""}
          </article>`).join("")}
        </section>`).join("")}</div>
      ${sourceNote([["compendium", "Artifact Perks"], a.perks.some((p) => p.eg) && ["endgame", "Artifact Mods"]].filter(Boolean))}`;
  }

  function sourceNote(list) {
    return `<p class="source-note">Sources: ${list.map(([src, tab]) => {
      const s = S.meta.sources[src];
      return `<a href="${esc(sheetUrl(src, tab) || "#")}" target="_blank" rel="noopener">${esc(s?.title || src)}${tab ? ` (${esc(tab)})` : ""}</a> by ${esc(s?.author || "")}`;
    }).join("; ")}.</p>`;
  }

  // ------------------------------------------------------------ wiki: entry pages
  async function renderItem(id) {
    const e = S.byId.get(id);
    if (!e) { app.innerHTML = `<p>That page doesn't exist. <a href="#/">Back home</a></p>`; return; }
    const conf = WIKI[e.cat];
    const art = e.cat === "artifact-perk" && artifacts().find((a) => a.name === e.artifact);
    const trail = [["Home", "#/"]];
    if (art) trail.push(["Artifacts", "#/wiki/artifacts"], [splitArtifact(art.name)[0], `#/artifact/${art.slug}`]);
    else if (conf) trail.push([conf.title, `#/wiki/${e.cat}`]);
    trail.push([e.name]);

    const c = CATS[e.cat] || {};
    const info = [];
    const add = (k, v) => v && info.push([k, v]);
    add("Type", c.label);
    add("Element", e.el);
    add("Class", e.cls);
    add("Exotic perk", e.perk);
    add("Frame", e.frame);
    add("Source", e.source);
    if (art) info.push(["Artifact", `<a href="#/artifact/${art.slug}">${esc(art.name)}</a>`, true]);
    add("Column", e.column && (e.cat === "artifact-perk" ? `${e.column} of 3` : e.column));
    add("Cost", e.cost);
    add("Armor slot", e.cat === "armor-mod" && e.slot);
    add("Group", e.group);
    add("Stat changes", e.stats);
    add("Notes", e.note);
    add("Modified by", e.mods?.join(", "));

    const body = e.pieces?.length
      ? e.pieces.map((p) => `<section class="piece"><h2>${esc(p.count)}: ${esc(p.name)}</h2><div class="desc">${fmt(p.desc)}</div></section>`).join("")
      : `<div class="desc">${fmt(e.desc)}</div>`;

    const roles = rolesOf(e);
    const kwChips = Object.entries(roles).filter(([, r]) => r.has("produce") || r.has("use")).map(([k, r]) => {
      const g = S.kwByName.get(k)?.group || "General";
      const role = [r.has("produce") && "makes", r.has("use") && "uses"].filter(Boolean).join(" + ");
      return `<a class="chip el-${esc(g)}" href="#/explore?kw=${encodeURIComponent(k)}"><span class="dot"></span>${esc(k)} <span class="role">${role}</span></a>`;
    }).join("");

    // siblings for wiki-style navigation
    let sibs = [];
    if (art) sibs = art.perks;
    else if (conf) sibs = S.entries.filter((o) => o.cat === e.cat && conf.group(o) === conf.group(e));
    sibs = sibs.filter((o) => o !== e).slice(0, 40);
    const egBlock = endgameHTML(e);

    app.innerHTML = `
      ${crumbs(trail)}
      <div class="wiki">
        <article class="wiki-main">
          <h1 class="${c.exotic ? "exotic" : ""}">${esc(e.name)}</h1>
          <div class="detail-meta">${tagsFor(e)}</div>
          ${body}
          ${e.cat === "verb" ? "" : glossaryBoxHTML([e.desc, ...(e.pieces || []).map((x) => x.desc)], [], "Keywords explained")}
          ${egBlock}
          ${kwChips ? `<section class="wiki-sec"><h2>Keywords</h2><p class="muted small">Each one lists everything else that makes or uses it.</p><div class="kwlist">${kwChips}</div></section>` : ""}
          <section class="wiki-sec" data-rollers hidden></section>
          <p class="legend"><span class="pvp">[bracketed] = PvP value</span><span class="enh">↑ = enhanced or catalyst value</span><span>? = not yet tested</span></p>
        </article>
        <aside class="wiki-side">
          <dl class="infobox">${info.map(([k, v, raw]) => `<dt>${esc(k)}</dt><dd>${raw ? v : fmt(String(v))}</dd>`).join("")}</dl>
          <div class="side-actions">
            ${e.cat === "exotic-weapon" ? `<a class="btn" data-weaponlink hidden>Perks and stats</a>` : ""}
            <a class="btn" href="${esc(sheetUrl("compendium", e.sheet) || "#")}" target="_blank" rel="noopener">Open in the Compendium</a>
          </div>
          ${sibs.length ? `<nav class="sibs" aria-label="More like this"><h2>${art ? "Also on this artifact" : (conf?.group(e) || "").length <= 1 ? `More ${esc(conf.title.toLowerCase())}` : `More ${esc(conf?.group(e) || "")}`}</h2><ul>${sibs.map((o) => `<li><a href="${itemHref(o)}" class="${elClass(o)}">${esc(o.name)}</a></li>`).join("")}</ul></nav>` : ""}
        </aside>
      </div>
      ${sourceNote([["compendium", e.sheet], e.eg && ["endgame", e.eg[0].tab], e.egExotic && ["endgame", "Exotic Weapons"]].filter(Boolean))}`;


    // weapon-side extras need the (bigger) weapon file
    if (["weapon-trait", "origin-trait", "intrinsic", "exotic-weapon"].includes(e.cat)) {
      await ensureWeapons();
      if (location.hash !== `#/item/${encodeURIComponent(id)}` && location.hash !== `#/item/${id}`) return;
      if (e.cat === "exotic-weapon") {
        const w = S.weaponByKey.get(normName(e.name));
        const a = app.querySelector("[data-weaponlink]");
        if (w && a) { a.href = `#/weapon/${w.slug}`; a.hidden = false; }
        return;
      }
      const rollers = e.cat === "intrinsic"
        ? S.weapons.weapons.filter((w) => normName(w.frame) === normName(e.name.split(" (")[0]))
        : [...(S.rollers.get(normName(e.name)) || [])];
      if (!rollers.length) return;
      rollers.sort((a, b) => tierRank(a.eg?.[0]?.tier) - tierRank(b.eg?.[0]?.tier) || a.n.localeCompare(b.n));
      const sec = app.querySelector("[data-rollers]");
      sec.hidden = false;
      sec.innerHTML = `<h2>${e.cat === "intrinsic" ? "Weapons with this frame" : "Weapons that can roll it"} <span class="muted">${rollers.length}</span></h2>
        <ul class="roller-list">${rollers.map((w) => `<li><a href="#/weapon/${w.slug}" class="el-${esc(w.el)}">${w.icon ? `<img src="${BNET}${esc(w.icon)}" alt="" loading="lazy" width="32" height="32">` : ""}<span>${esc(w.n)}</span>${tierBadge(w.eg?.[0]?.tier, "Endgame Analysis tier")}<span class="muted">${esc(w.type)}</span></a></li>`).join("")}</ul>`;
    }
  }

  // ------------------------------------------------------------ weapons index
  function readWeaponParams() {
    const { q } = parseHash();
    return { q: q.get("q") || "", type: q.get("type") || "", el: q.get("el") || "", tier: q.get("tier") || "", ammo: q.get("ammo") || "", rarity: q.get("rarity") || "", perk: q.get("perk") || "", sort: q.get("sort") || "", cat: q.get("cat") || "" };
  }
  const weaponHash = (p) => { const q = new URLSearchParams(Object.entries(p).filter(([, v]) => v)); return `#/weapons${q.toString() ? "?" + q : ""}`; };

  // the Compendium writes catalyst effects as paragraphs that start with "↑Name:" or "↑Catalyst"
  function splitCatalystText(desc) {
    // the catalyst section runs from its first "↑Name:" paragraph to the end of the entry
    const paras = (desc || "").split(/\n\s*\n/);
    const start = paras.findIndex((t) => /^↑(Catalyst\b|[^\n:]{1,80}:)/.test(t.trim()));
    if (start < 0) return { cat: [], rest: paras.join("\n\n") };
    return { cat: paras.slice(start), rest: paras.slice(0, start).join("\n\n") };
  }
  function compendiumExotic(w) {
    if (w.tier !== "Exotic") return null;
    if (!S.compExotic) {
      S.compExotic = new Map();
      S.entries.filter((e) => e.cat === "exotic-weapon").forEach((e) => { if (!S.compExotic.has(normName(e.name))) S.compExotic.set(normName(e.name), e); });
    }
    return S.compExotic.get(normName(w.n)) || null;
  }
  const hasCatalyst = (w) => !!(w.catalyst || splitCatalystText(compendiumExotic(w)?.desc).cat.length);

  async function renderWeapons(view) {
    if (!S.weapons) app.innerHTML = `<p class="loading">Loading weapons…</p>`;
    await ensureWeapons();
    if (view === "exotic-ratings") return renderExoticRatings();
    const p = readWeaponParams();
    const all = S.weapons.weapons;
    const types = [...new Set(all.map((w) => w.type))].sort();
    const terms = p.q.toLowerCase().split(/\s+/).filter(Boolean);
    const perkKey = normName(p.perk);
    let rows = all.filter((w) => (!p.type || w.type === p.type) && (!p.el || w.el === p.el) && (!p.ammo || w.ammo === p.ammo) &&
      (!p.rarity || w.tier === p.rarity) && (!p.tier || w.eg?.some((x) => x.tier === p.tier)) && (!p.cat || hasCatalyst(w)) &&
      (!perkKey || w.cols.some((c) => c.perks.some((h) => normName(S.weapons.perks[h]?.n) === perkKey))) &&
      (!terms.length || terms.every((t) => (w._hay ||= [w.n, w.type, w.frame, w.src, w.el].join(" ").toLowerCase()).includes(t))));
    const sorters = {
      tier: (a, b) => tierRank(a.eg?.[0]?.tier) - tierRank(b.eg?.[0]?.tier) || (+a.eg?.[0]?.rank || 999) - (+b.eg?.[0]?.rank || 999) || a.n.localeCompare(b.n),
      type: (a, b) => a.type.localeCompare(b.type) || (+a.eg?.[0]?.rank || 999) - (+b.eg?.[0]?.rank || 999) || a.n.localeCompare(b.n),
      "": (a, b) => a.n.localeCompare(b.n),
    };
    rows = rows.slice().sort(sorters[p.sort] || sorters[""]);
    const limit = 240;
    const chip = (key, val, label, extra = "") => `<button type="button" class="chip ${extra}" aria-pressed="${p[key] === val}" data-wf="${key}" data-v="${esc(val)}">${label}</button>`;
    app.innerHTML = `
      ${crumbs([["Home", "#/"], ["Weapons"]])}
      <h1>Weapons</h1>
      <p class="intro">Every legendary and exotic weapon in Bungie's item data with every perk it can roll. Tiers and suggested rolls come from <a href="${esc(sheetUrl("endgame", "Autos") || "#")}" target="_blank" rel="noopener">Endgame Analysis</a> by ${esc(S.meta.sources.endgame?.author || "")}.</p>
      <nav class="tabbar" aria-label="Weapon views"><a href="#/weapons" aria-current="page">All weapons</a><a href="#/weapons/exotic-ratings">Exotic ratings table</a></nav>
      <div class="wfilters">
        <input class="input" type="search" placeholder="Search by name, frame, source…" value="${esc(p.q)}" data-wq aria-label="Search weapons">
        <select class="input" data-wsel="type" aria-label="Weapon type"><option value="">All types</option>${types.map((t) => `<option ${t === p.type ? "selected" : ""}>${esc(t)}</option>`).join("")}</select>
        <input class="input" list="perknames" placeholder="Can roll perk…" value="${esc(p.perk)}" data-wperk aria-label="Can roll this perk">
        <datalist id="perknames">${[...new Set(Object.values(S.weapons.perks).filter((x) => /Trait|Origin/.test(x.t) && !x.e).map((x) => x.n))].sort().map((n) => `<option value="${esc(n)}">`).join("")}</datalist>
        <select class="input" data-wsel="sort" aria-label="Sort"><option value="">Sort: name</option><option value="tier" ${p.sort === "tier" ? "selected" : ""}>Sort: Endgame tier</option><option value="type" ${p.sort === "type" ? "selected" : ""}>Sort: type, then rank</option></select>
      </div>
      <div class="wfilters">
        <div class="chips">${chip("rarity", "Legendary", "Legendary")}${chip("rarity", "Exotic", "Exotic", "chip-exotic")}${chip("cat", "1", "Has catalyst", "chip-exotic")}</div>
        <div class="chips">${["Kinetic", "Arc", "Solar", "Void", "Stasis", "Strand"].map((el) => chip("el", el, `<span class="dot"></span>${el}`, `el-${el}`)).join("")}</div>
        <div class="chips">${["Primary", "Special", "Heavy"].map((a) => chip("ammo", a, a)).join("")}</div>
        <div class="chips">${TIER_ORDER.slice(0, 6).map((t) => chip("tier", t, `Tier ${t}`)).join("")}</div>
      </div>
      <p class="muted">${rows.length.toLocaleString()} weapon${rows.length === 1 ? "" : "s"}${p.perk ? ` that can roll ${esc(p.perk)}` : ""}</p>
      <ul class="wgrid">${rows.slice(0, limit).map(weaponTile).join("")}</ul>
      ${rows.length > limit ? `<button type="button" class="btn" data-wmore style="margin-top:10px">Show all ${rows.length}</button>` : ""}
      ${!rows.length ? `<p>No weapons match. Clear a filter or check the perk name.</p>` : ""}`;

    let t;
    const upd = (patch) => go(weaponHash({ ...readWeaponParams(), ...patch }), true);
    app.querySelector("[data-wq]").oninput = (ev) => { clearTimeout(t); t = setTimeout(() => { upd({ q: ev.target.value }); focusEnd("[data-wq]"); }, 220); };
    app.querySelector("[data-wperk]").onchange = (ev) => upd({ perk: ev.target.value.trim() });
    app.querySelectorAll("[data-wsel]").forEach((s) => { s.onchange = () => upd({ [s.dataset.wsel]: s.value }); });
    app.onclick = (ev) => {
      const b = ev.target.closest("button");
      if (!b) return;
      if (b.dataset.wf) { const cur = readWeaponParams(); upd({ [b.dataset.wf]: cur[b.dataset.wf] === b.dataset.v ? "" : b.dataset.v }); }
      if (b.dataset.wmore !== undefined) { app.querySelector(".wgrid").insertAdjacentHTML("beforeend", rows.slice(limit).map(weaponTile).join("")); b.remove(); }
    };
  }

  function focusEnd(sel) {
    const el = app.querySelector(sel);
    if (el) { el.focus(); const v = el.value; el.value = ""; el.value = v; }
  }

  function weaponTile(w) {
    const pick = w.eg?.[0];
    return `<li><a class="wtile el-${esc(w.el)} ${w.tier === "Exotic" ? "exotic" : ""}" href="#/weapon/${w.slug}">
      ${w.icon ? `<img src="${BNET}${esc(w.icon)}" alt="" loading="lazy" width="48" height="48">` : `<span class="wt-noimg"></span>`}
      <span class="wt-text"><span class="wt-name">${esc(w.n)}</span><span class="wt-sub">${esc([w.el, w.frame, w.type].filter(Boolean).join(" · "))}</span></span>
      ${pick?.tier ? tierBadge(pick.tier, "Endgame Analysis tier") : w.egExotic?.tier ? tierBadge(w.egExotic.tier, "Endgame Analysis tier") : ""}
    </a></li>`;
  }

  function renderExoticRatings() {
    const rows = S.weapons.exotics.map((x) => [
      x.tier || "", x.name, x.ammoType || "", (x.tags || []).join(", "),
      RATING[x.roam] || x.roam || "", RATING[x.dps] || x.dps || "", RATING[x.challenge] || x.challenge || "", RATING[x.speed] || x.speed || "",
      x.summary || "", x.usage || "",
    ]);
    const table = { columns: ["Tier", "Weapon", "Ammo", "Tags", "Roaming", "Boss DPS", "Challenge", "Speedrun", "What it does", "Verdict"], rows };
    app.innerHTML = `
      ${crumbs([["Home", "#/"], ["Weapons", "#/weapons"], ["Exotic ratings"]])}
      <h1>Exotic weapon ratings</h1>
      <p class="intro">How Endgame Analysis by ${esc(S.meta.sources.endgame?.author || "")} rates each exotic for roaming, boss DPS, challenges and speedruns (Optimal, Viable, Situational, Wasted).</p>
      <nav class="tabbar" aria-label="Weapon views"><a href="#/weapons">All weapons</a><a href="#/weapons/exotic-ratings" aria-current="page">Exotic ratings table</a></nav>
      <div class="table-tools"><input class="input" type="search" placeholder="Filter exotics…" data-tfilter aria-label="Filter exotics"><span class="muted" data-tcount></span></div>
      <div class="tablewrap" data-twrap></div>`;
    mountTable(app.querySelector("[data-twrap]"), table, app.querySelector("[data-tfilter]"), app.querySelector("[data-tcount]"), {
      sortDefault: 0, tierCol: 0,
      cell: (v, i) => {
        if (i === 0) return tierBadge(v);
        if (i === 1) { const w = S.weaponByKey.get(normName(v)); return w ? `<span class="cellpic">${w.icon ? weaponThumb(w, 40) : ""}<a href="#/weapon/${w.slug}" style="color:var(--exotic)">${esc(v)}</a></span>` : esc(v); }
        return esc(v);
      },
    });
  }

  // ------------------------------------------------------------ weapon page
  async function renderWeapon(slug, perkSel) {
    if (!S.weapons) app.innerHTML = `<p class="loading">Loading weapon…</p>`;
    await Promise.all([ensureWeapons(), ensureTables()]);
    const w = S.weaponBySlug.get(slug);
    if (!w) { app.innerHTML = `<p>Weapon not found. <a href="#/weapons">All weapons</a></p>`; return; }
    const P = S.weapons.perks;
    const recommended = new Map(); // normName -> label
    (w.eg || []).forEach((x) => {
      ["perk1", "perk2", "origin", "barrel", "mag"].forEach((k) => (x[k] || []).forEach((n, i) => {
        const key = normName(n);
        if (!recommended.has(key)) recommended.set(key, i === 0 ? "Top pick" : "Also suggested");
      }));
    });
    const altSet = new Set(Object.values(w.alts || {}).flat().map((h) => normName(P[h]?.n)));
    const pick = w.eg?.[0];
    const comp = compendiumExotic(w);
    const compSplit = splitCatalystText(comp?.desc);

    // collapse enhanced copies into their base perk
    const enhOf = {}; // base perk hash -> its enhanced copy in the same column
    const colHTML = (c, ci) => {
      const seen = new Map();
      c.perks.forEach((h) => {
        const p = P[h]; if (!p) return;
        const k = normName(p.n);
        const x = seen.get(k) || seen.set(k, { base: null, enh: null }).get(k);
        if (p.e) x.enh ||= h; else x.base ||= h;
      });
      const items = [...seen.values()].map(({ base, enh }) => {
        const h = base || enh;
        if (base && enh) enhOf[base] = enh;
        return { h, p: P[h], enhanced: !!enh };
      });
      // deprecated perks sink to the bottom of their column
      items.sort((a, b) => isDeprecated(a.p) - isDeprecated(b.p));
      const retired = (c.retired || []).map((h) => P[h]).filter((p) => p && !p.e && !seen.has(normName(p.n)));
      return `<section class="pcol" aria-label="${esc(c.label)}">
        <h3>${esc(c.label)}</h3>
        <ul>${items.map(({ h, p, enhanced }) => {
          const rec = recommended.get(normName(p.n));
          const alt = altSet.has(normName(p.n));
          const dep = isDeprecated(p);
          return `<li><button type="button" class="pk ${rec ? "rec" : ""} ${alt ? "alt" : ""} ${dep ? "deprecated" : ""} ${perkSel === String(h) ? "sel" : ""}" data-perk="${h}" ${c.noPick ? "" : `data-col="${ci}"`} title="${esc(p.n)}${dep ? " (deprecated)" : ""}${p.eg?.tier ? ` (Endgame tier ${p.eg.tier})` : ""}">
            ${p.i ? `<img src="${BNET}${esc(p.i)}" alt="" loading="lazy" width="36" height="36">` : `<span class="pk-noimg"></span>`}
            <span class="pk-name">${esc(p.n)}${enhanced ? `<span class="pk-enh" title="Enhanced version available">↑</span>` : ""}${dep ? `<span class="pk-dep">Deprecated</span>` : ""}</span>
            ${p.eg?.tier ? `<span class="pk-tier tier-${esc(p.eg.tier)}">${esc(p.eg.tier)}</span>` : ""}
          </button></li>`;
        }).join("")}</ul>
        ${retired.length ? `<details class="retired"><summary>${retired.length} retired</summary><p>${retired.map((p) => esc(p.n)).join(", ")}</p></details>` : ""}
      </section>`;
    };

    // stat bar with the picked perks' change drawn on top: green for gains, red for losses
    // stat row: base value in white, the change from your picks in green (gain) or red (loss)
    const statBar = ([h, v], nv = v) => {
      const name = S.weapons.statNames[h] || h;
      const bar = (!/Rounds Per Minute|Magazine|Charge Time|Draw Time|Ammo Generation|Swing Speed|Ammo Capacity|Blast Radius|Velocity|Recoil/i.test(name) || /Recoil Direction/i.test(name)) && v <= 100;
      const clamp = (x) => Math.max(0, Math.min(100, x));
      if (bar) nv = clamp(nv);
      const d = nv - v;
      const lo = Math.min(clamp(v), clamp(nv)), hi = Math.max(clamp(v), clamp(nv));
      const delta = d ? `<span class="st-d ${d > 0 ? "up" : "down"}">${d > 0 ? "+" : ""}${d}</span>` : "";
      return `<div class="stat"><span class="st-name">${esc(name)}</span>${bar
        ? `<span class="st-bar"><span class="st-base" style="width:${lo}%"></span>${hi > lo ? `<span class="${nv > v ? "st-plus" : "st-minus"}" style="left:${lo}%;width:${hi - lo}%"></span>` : ""}</span>`
        : `<span class="st-bar st-none"></span>`}<span class="st-val">${esc(nv)}${delta}</span></div>`;
    };

    const whyList = (x) => {
      const rows = [...(x.perk1 || []), ...(x.perk2 || []), ...(x.origin || [])].filter((n) => n && n.toLowerCase() !== "none").map((n) => {
        const p = Object.values(P).find((pp) => normName(pp.n) === normName(n) && !pp.e);
        const eg = p?.eg;
        return `<li><b>${esc(n)}</b> ${tierBadge(eg?.tier, "Endgame perk tier")}${eg?.trigger || eg?.effect ? `<span class="why-te">${esc(eg.trigger || "")}${eg.trigger && eg.effect ? " → " : ""}${esc(eg.effect || "")}</span>` : ""}</li>`;
      });
      return rows.length ? `<ul class="why">${rows.join("")}</ul>` : "";
    };
    const altsHTML = () => {
      if (!w.alts) return "";
      return `<section class="wcard-sec"><h3>Other strong perks it can roll</h3><p class="muted small">Not in the suggested roll, but rated A or better as perks in Endgame Analysis.</p>
        ${Object.entries(w.alts).map(([col, hs]) => `<p><span class="muted">${esc(col)}:</span> ${hs.map((h) => { const p = P[h]; return `<button type="button" class="linkish" data-perk="${h}">${esc(p.n)}</button> ${tierBadge(p.eg?.tier, "Endgame perk tier")}`; }).join(", ")}</p>`).join("")}</section>`;
    };

    const verdict = w.eg?.length ? w.eg.map((x, i) => `
      <section class="wcard-sec">
        <h3>${w.eg.length > 1 ? `${esc(x.variant || "Standard version")}: ` : ""}Endgame verdict ${tierBadge(x.tier, "Endgame Analysis tier")}${x.rank ? ` <span class="muted">#${esc(x.rank)} in ${esc(x.type)}</span>` : ""}</h3>
        ${x.notes ? `<p class="blurb">${esc(x.notes[0].toUpperCase() + x.notes.slice(1))}</p>` : ""}
        <dl class="kv roll">
          ${x.barrel?.length ? `<dt>Barrel</dt><dd>${esc(x.barrel.join(" or "))}</dd>` : ""}
          ${x.mag?.length ? `<dt>Magazine</dt><dd>${esc(x.mag.join(" or "))}</dd>` : ""}
          ${x.perk1?.length ? `<dt>Trait 1</dt><dd>${esc(x.perk1.join(" or "))}</dd>` : ""}
          ${x.perk2?.length ? `<dt>Trait 2</dt><dd>${esc(x.perk2.join(" or "))}</dd>` : ""}
          ${x.origin?.length ? `<dt>Origin</dt><dd>${esc(x.origin.join(" or "))}</dd>` : ""}
          ${x.mw ? `<dt>Masterwork</dt><dd>${esc(x.mw)}</dd>` : ""}
        </dl>
        <h4>Why these perks</h4>${whyList(x)}
      </section>`).join("") : w.egExotic ? `
      <section class="wcard-sec"><h3>Endgame rating ${tierBadge(w.egExotic.tier)}</h3>
        ${w.egExotic.summary ? `<p class="blurb">${esc(w.egExotic.summary)}</p>` : ""}
        <ul class="eg-rates">${[["Roaming", w.egExotic.roam], ["Boss DPS", w.egExotic.dps], ["Challenge", w.egExotic.challenge], ["Speedrun", w.egExotic.speed]].filter(([, v]) => v).map(([k, v]) => `<li><span class="muted">${k}</span> <b>${esc(RATING[v] || v)}</b></li>`).join("")}</ul>
        ${w.egExotic.usage ? `<p class="muted">${esc(w.egExotic.usage)}</p>` : ""}</section>`
      : `<section class="wcard-sec"><h3>Not ranked</h3><p class="muted">Endgame Analysis doesn't rank this weapon, usually because it's outclassed or no longer obtainable. Perk ratings below still apply.</p></section>`;

    // stat math: invested points -> shown value through the weapon's stat group (Bungie's lookup tables)
    const group = S.weapons.statGroups?.[w.sg] || {};
    const baseInv = Object.fromEntries(w.inv || []);
    const shownStat = (h, extra, fallback) => {
      const t = group[h]?.t;
      if (!t?.length || baseInv[h] === undefined) return fallback + extra;
      const x = Math.max(0, baseInv[h] + extra);
      if (x <= t[0][0]) return t[0][1];
      for (let i = 1; i < t.length; i++) {
        if (x <= t[i][0]) { const [v0, w0] = t[i - 1], [v1, w1] = t[i]; return Math.round(w0 + ((x - v0) / (v1 - v0)) * (w1 - w0)); }
      }
      return t[t.length - 1][1];
    };
    const statSummary = (p) => (p?.s || []).filter(([sh]) => group[sh] || w.stats.some(([h]) => String(h) === String(sh))).map(([sh, v]) => `${v > 0 ? "+" : ""}${v} ${S.weapons.statNames[sh] || ""}`).join(", ");
    const inGroup = (p) => (p?.s || []).some(([sh]) => w.stats.some(([h]) => String(h) === String(sh)));
    const mwOptions = (S.weapons.plugSets?.[w.mw] || []).map(([h]) => P[h]).map((p, i) => [S.weapons.plugSets[w.mw][i][0], p])
      // only masterworks named for a stat this weapon actually shows (no Persistence on a hand cannon)
      .filter(([, p]) => {
        if (!inGroup(p)) return false;
        const named = p.n.replace(/^(Masterworked|Tier \d+): /, "");
        const isStatName = Object.values(S.weapons.statNames).includes(named);
        return !isStatName || w.stats.some(([sh]) => S.weapons.statNames[sh] === named);
      })
      .map(([h, p]) => [h, `${p.n.replace(/^Masterworked: /, "")} (${statSummary(p)})`]);
    const modPairs = S.weapons.plugSets?.[w.mods] || [];
    const modEnh = Object.fromEntries(modPairs.filter((x) => x[1]).map(([a, b]) => [a, b]));
    const modOptions = modPairs.map(([h]) => [h, P[h]]).filter(([, p]) => p)
      .map(([h, p]) => [h, `${p.n}${statSummary(p) ? ` (${statSummary(p)})` : ""}`]);

    // icon grid for masterwork / mod / catalyst choices; the chosen one's name shows under the grid
    const gearRow = (kind, label, options) => `<div class="gear-row">
      <div class="gear-head"><span class="gear-label">${esc(label)}</span><span class="gear-sel muted" data-gearname="${kind}">None</span></div>
      <div class="gear-opts">${options.map(([h, text, icon]) => {
        const i = icon || P[h]?.i;
        return `<button type="button" class="gear" data-gearpick="${kind}" data-h="${h}" aria-pressed="false" title="${esc(text)}" aria-label="${esc(text)}">${i ? `<img src="${BNET}${esc(i)}" alt="" width="40" height="40" loading="lazy">` : `<span class="gear-noimg">${esc(text.slice(0, 2))}</span>`}</button>`;
      }).join("")}</div></div>`;
    const gearLabel = Object.fromEntries([...mwOptions, ...modOptions].map(([h, text]) => [h, text]));

    app.innerHTML = `
      ${crumbs([["Home", "#/"], ["Weapons", "#/weapons"], [w.n]])}
      <header class="whero ${w.tier === "Exotic" ? "exotic" : ""} el-${esc(w.el)}" ${w.shot ? `style="--shot:url('${BNET}${esc(w.shot)}')"` : ""}>
        ${w.icon ? `<img class="wh-icon" src="${BNET}${esc(w.icon)}" alt="" width="84" height="84">` : ""}
        <div>
          <h1>${esc(w.n)}</h1>
          <p class="wh-type">${esc([w.tier, w.type].join(" "))}</p>
          <div class="wh-tags"><span class="tag tag-el">${esc(w.el)}</span><span class="tag">${esc(w.ammo)} ammo</span><span class="tag">${esc(w.slot)} slot</span>${w.frame ? `<button type="button" class="tag tag-btn" data-perk="${w.frameHash}">${esc(w.frame)}</button>` : ""}${w.craftable ? `<span class="tag">Craftable</span>` : ""}${w.hasAdept ? `<span class="tag">Adept version</span>` : ""}</div>
          ${w.flavor ? `<p class="wh-flavor">${esc(w.flavor)}</p>` : ""}
          ${w.src ? `<p class="wh-src">${esc(w.src)}</p>` : ""}
        </div>
      </header>
      <div class="wpage">
        <div class="wpage-main">
          <section class="perks-grid" aria-label="Perk pool">
            <div class="pg-head"><h2>Perks it can roll</h2><span class="legend"><span><i class="lg rec"></i>Suggested roll</span><span><i class="lg alt"></i>Other strong pick</span><span><i class="lg pick"></i>Your pick</span><span>↑ enhanced available</span></span></div>
            <div class="pcols">${(w.tier === "Exotic" && w.frameHash ? [{ label: "Exotic perk", perks: [w.frameHash], noPick: true }, ...w.cols] : w.cols).map(colHTML).join("")}</div>
          </section>
          <section class="perk-detail" data-perkdetail aria-live="polite"><p class="muted">Select a perk to see what it does.</p></section>
          ${catalystHTML(w, compSplit.cat)}
          ${comp && compSplit.rest.trim() ? `<section class="wcard-sec"><h3>Compendium notes</h3><div class="desc">${fmt(compSplit.rest)}</div><p><a href="${itemHref(comp)}">Open the full Compendium entry</a></p></section>` : ""}
        </div>
        <aside class="wpage-side">
          ${w.stats?.length ? `<section class="wcard-sec" data-statsbox><h3>Stats</h3>
            <div class="stat-tools"><label><input type="checkbox" data-enh> Enhanced perks</label><button type="button" class="btn btn-sm" data-clearroll hidden>Clear picks</button></div>
            ${mwOptions.length || modOptions.length || w.catalyst?.s ? `<div class="stat-pickers">
              ${mwOptions.length ? gearRow("mw", "Masterwork", mwOptions) : ""}
              ${mwOptions.length ? `<div class="gear-row mw-bonus" data-mwbonus hidden>
                <div class="gear-head"><span class="gear-label">Bonus to other stats</span><span class="gear-sel muted">fully masterworked</span></div>
                <div class="chips">${MW_BONUS.map(([v, label, tip]) => `<button type="button" class="chip chip-sm" data-mwb="${v}" aria-pressed="false" title="${esc(tip)}">${esc(label)}</button>`).join("")}</div>
              </div>` : ""}
              ${modOptions.length ? gearRow("mod", "Weapon mod", modOptions) : ""}
              ${w.catalyst?.s ? gearRow("cat", "Catalyst", [["cat", `${w.catalyst.n} (${w.catalyst.s.map(([sh, v]) => `${v > 0 ? "+" : ""}${v} ${S.weapons.statNames[sh] || ""}`).join(", ")})`, w.catalyst.i]]) : ""}
            </div>` : ""}
            <p class="muted roll-hint" data-rollhint>Click perks in each column, or pick a masterwork and mod, to build a roll; the bars update as you go.</p>
            <div class="stats" data-statbars></div>
            <p class="muted st-note">Calculated the way the game does it: perk, masterwork and mod points are added to the weapon's hidden stat values, then run through Bungie's per-weapon lookup tables (that's why a mag perk adds 2 rounds on one gun and 6 on another).</p></section>` : ""}
          ${verdict}
          ${altsHTML()}
          ${archetypeCard(w)}
        </aside>
      </div>
      <p class="source-note">Weapon data from Bungie's Destiny 2 item manifest${S.meta.bungieVersion ? ` (${esc(S.meta.bungieVersion)})` : ""}. ${w.eg || w.egExotic ? `Tiers, suggested rolls and perk ratings from <a href="${esc(sheetUrl("endgame", w.tier === "Exotic" ? "Exotic Weapons" : w.eg?.[0]?.tab) || "#")}" target="_blank" rel="noopener">Endgame Analysis</a> by ${esc(S.meta.sources.endgame?.author || "")}; the summary is generated from that sheet's data.` : ""}${comp ? ` Exact values from the Destiny Data Compendium.` : ""}</p>`;

    const showPerk = (h) => {
      const p = P[h];
      if (!p) return;
      app.querySelectorAll(".pk.sel, .tag-btn.sel").forEach((x) => x.classList.remove("sel"));
      app.querySelectorAll(`[data-perk="${h}"]`).forEach((x) => x.classList.add("sel"));
      const ce = compendiumPerk(p.n);
      const box = app.querySelector("[data-perkdetail]");
      box.innerHTML = `
        <div class="pd-head">${p.i ? `<img src="${BNET}${esc(p.i)}" alt="" width="44" height="44">` : ""}<div><h3>${esc(p.n)} ${tierBadge(p.eg?.tier, "Endgame perk tier")}</h3><span class="muted">${esc(p.t)}</span></div></div>
        ${isDeprecated(p) ? `<p class="dep-note"><b>Deprecated.</b> Bungie still lists ${esc(p.n)} in a shared magazine pool, but it isn't part of this weapon's real roll pool.</p>` : ""}
        ${p.d ? `<p>${esc(p.d)}</p>` : ""}
        ${p.s?.length ? `<p class="muted">${p.s.map(([sh, v]) => `${v > 0 ? "+" : ""}${v} ${esc(S.weapons.statNames[sh] || "")}`).join(" · ")}</p>` : ""}
        ${p.eg?.trigger || p.eg?.effect ? `<p><span class="muted">Endgame Analysis:</span> ${esc(p.eg.trigger || "")}${p.eg.trigger && p.eg.effect ? " → " : ""}${esc(p.eg.effect || "")}</p>` : ""}
        ${p.eg?.analysis ? `<p class="muted">${esc(p.eg.analysis)}</p>` : ""}
        ${ce ? `<div class="pd-comp"><h4>Exact values (Compendium)</h4><div class="desc">${fmt(ce.desc)}</div><p><a href="${itemHref(ce)}">Open ${esc(ce.name)}</a></p></div>` : ""}
        ${glossaryBoxHTML([p.d, ce?.desc, p.eg?.effect])}
        <p><a href="#/weapons?perk=${encodeURIComponent(p.n)}">Other weapons that can roll ${esc(p.n)}</a></p>`;
    };
    // the roll you're building: column index -> base perk hash
    const picks = new Map();
    let useEnh = false;
    const gear = { mw: "", mod: "", cat: false, mwb: 0 };
    const drawStats = () => {
      const box = app.querySelector("[data-statbars]");
      if (!box) return;
      const delta = {};
      const add = (p) => (p?.s || []).forEach(([sh, v]) => { delta[sh] = (delta[sh] || 0) + v; });
      for (const h of picks.values()) add(P[(useEnh && enhOf[h]) || h]);
      if (gear.mw) {
        add(P[gear.mw]);
        // max-level masterwork: +N to every other stat it lists, if the weapon has that stat
        if (gear.mwb) (P[gear.mw]?.c || []).forEach((sh) => { if (w.stats.some(([h]) => String(h) === String(sh))) delta[sh] = (delta[sh] || 0) + gear.mwb; });
      }
      if (gear.mod) add(P[(useEnh && modEnh[gear.mod]) || gear.mod]);
      if (gear.cat && w.catalyst?.s) add({ s: w.catalyst.s });
      box.innerHTML = w.stats.map(([h, v]) => statBar([h, v], shownStat(h, delta[h] || 0, v))).join("");
      app.querySelector("[data-clearroll]").hidden = !picks.size && !gear.mw && !gear.mod && !gear.cat;
      app.querySelector("[data-rollhint]").hidden = !!picks.size;
    };
    const markPicks = () => {
      app.querySelectorAll(".pk.picked").forEach((x) => x.classList.remove("picked"));
      for (const [ci, h] of picks) app.querySelector(`.pk[data-col="${ci}"][data-perk="${h}"]`)?.classList.add("picked");
    };
    const markGear = () => {
      app.querySelectorAll("[data-gearpick]").forEach((b) => {
        const k = b.dataset.gearpick;
        b.setAttribute("aria-pressed", String(k === "cat" ? gear.cat : gear[k] === b.dataset.h));
      });
      const bonusRow = app.querySelector("[data-mwbonus]");
      if (bonusRow) {
        bonusRow.hidden = !gear.mw || !(P[gear.mw]?.c || []).length;
        bonusRow.querySelectorAll("[data-mwb]").forEach((b) => b.setAttribute("aria-pressed", String(+b.dataset.mwb === gear.mwb)));
      }
      app.querySelectorAll("[data-gearname]").forEach((el) => {
        const k = el.dataset.gearname;
        el.textContent = k === "cat" ? (gear.cat ? "Applied" : "None") : (gearLabel[gear[k]] || "None");
      });
    };
    app.onchange = (ev) => { if (ev.target.matches("[data-enh]")) { useEnh = ev.target.checked; drawStats(); } };
    app.onclick = (ev) => {
      if (ev.target.closest("[data-clearroll]")) {
        picks.clear(); gear.mw = gear.mod = ""; gear.cat = false; gear.mwb = 0;
        markPicks(); markGear(); drawStats(); return;
      }
      const mb = ev.target.closest("[data-mwb]");
      if (mb) { gear.mwb = +mb.dataset.mwb; markGear(); drawStats(); return; }
      const g = ev.target.closest("[data-gearpick]");
      if (g) {
        const k = g.dataset.gearpick;
        if (k === "cat") gear.cat = !gear.cat;
        else {
          const had = gear.mw;
          gear[k] = gear[k] === g.dataset.h ? "" : g.dataset.h;
          if (gear[k]) showPerk(gear[k]);
          if (k === "mw" && gear.mw && !had && !gear.mwb) gear.mwb = 5; // a fresh masterwork starts at max tier
        }
        markGear(); drawStats(); return;
      }
      const b = ev.target.closest("[data-perk]");
      if (!b) return;
      if (b.dataset.col !== undefined) {
        const ci = b.dataset.col;
        if (picks.get(ci) === b.dataset.perk) picks.delete(ci); else picks.set(ci, b.dataset.perk);
        markPicks(); drawStats();
      }
      showPerk(b.dataset.perk);
      if (window.matchMedia("(max-width: 900px)").matches) app.querySelector("[data-perkdetail]").scrollIntoView({ behavior: "smooth", block: "nearest" });
    };
    // open on the top pick so the panel isn't empty
    const first = w.tier === "Exotic" ? w.frameHash : w.cols.find((c) => c.label.startsWith("Trait"))?.perks.find((h) => recommended.has(normName(P[h]?.n)));
    if (first) showPerk(first);
    drawStats();
  }

  // fully masterworked bonus to the other stats: Edge of Fate tiers give +tier, adept/enhanced weapons +3
  const MW_BONUS = [
    [0, "None", "No bonus to other stats"],
    [1, "Tier 1", "+1 to other stats"], [2, "Tier 2", "+2 to other stats"], [3, "Tier 3", "+3 to other stats (also what older adept and enhanced weapons get)"],
    [4, "Tier 4", "+4 to other stats"], [5, "Tier 5", "+5 to other stats"],
  ];

  // perks Bungie still lists but that don't actually roll
  const DEPRECATED_PERKS = new Set(["dropmag"]);
  const isDeprecated = (p) => !!p && DEPRECATED_PERKS.has(normName(p.n));


  // ------------------------------------------------------------ archetypes (Endgame Analysis)
  const typeKey = (t) => normName(t).replace(/s$/, "").replace("submachinegun", "smg").replace("combatbow", "bow");
  async function ensureTables() {
    if (!S.tables) S.tables = await (await fetch("data/tables.json")).json();
    return S.tables;
  }
  function archetypeRowsFor(type, ammo) {
    const t = S.tables?.archetypes;
    if (!t) return [];
    // grenade launchers split by loading: breech (special) vs drum (heavy)
    if (/grenade launcher/i.test(type)) {
      const sub = /breech/i.test(type) || ammo === "Special" ? "breech" : /heavy|drum/i.test(type) || ammo === "Heavy" ? "drum" : "";
      return t.rows.filter((r) => /grenade launcher/i.test(r[0]) && (!sub || r[0].toLowerCase().includes(sub)));
    }
    const k = typeKey(type.replace(/^rocket sidearm$/i, "sidearm"));
    return t.rows.filter((r) => typeKey(r[0]) === k);
  }
  const CHAMPION = { "Shield Piercing": "Anti-Barrier", "Disruption": "Anti-Overload", "Stagger": "Anti-Unstoppable" };
  function stunHTML(name, withLabel = true) {
    const b = S.tables?.archetypes?.breakers?.[name];
    if (!name) return `<span class="muted">None</span>`;
    const label = CHAMPION[name] || name;
    return `<span class="stun" title="${esc(label)} (${esc(name)})">${b?.icon ? `<img src="${BNET}${esc(b.icon)}" alt="${esc(label)}" width="26" height="26">` : ""}${withLabel ? `<span>${esc(label.replace("Anti-", ""))}</span>` : ""}</span>`;
  }
  // a real weapon from Bungie's data that represents an archetype row (best Endgame rank wins)
  function archetypeWeapon(row) {
    const k = typeKey(row[0].split(" - ")[0]);
    const ammo = /breech/i.test(row[0]) ? "Special" : /drum/i.test(row[0]) ? "Heavy" : "";
    const frame = normName(row[1].split(/\s(?:Jagged|Pack|Heavy Bolts|Accelerated|Spike|body|Assault)/)[0]);
    const pool = S.weapons.weapons.filter((w) => w.tier === "Legendary" && typeKey(w.type) === k && (!ammo || w.ammo === ammo) && w.icon);
    const byFrame = pool.filter((w) => { const f = normName(w.frame.replace(/ Frame$/, "")); return f && (f === frame || frame.startsWith(f) || f.startsWith(frame)); });
    const exact = byFrame.filter((w) => normName(w.frame.replace(/ Frame$/, "")) === frame);
    const list = exact.length ? exact : byFrame;
    list.sort((a, b) => tierRank(a.eg?.[0]?.tier) - tierRank(b.eg?.[0]?.tier) || (+a.eg?.[0]?.rank || 999) - (+b.eg?.[0]?.rank || 999));
    return list[0];
  }
  function weaponThumb(w, size = 40) {
    if (!w) return `<span class="thumb-empty" style="width:${size}px;height:${size}px"></span>`;
    return `<a class="thumb" href="#/weapon/${w.slug}" title="${esc(w.n)}" aria-label="${esc(w.n)}"><img src="${BNET}${esc(w.icon)}" alt="" width="${size}" height="${size}" loading="lazy"></a>`;
  }

  // ------------------------------------------------------------ armor: set bonuses | mods & stats
  // keyword dropdowns: one <details> per glossary keyword the text mentions, plus Armor Charge from the Game Mechanics tab
  function kwDropsHTML(text, label = "Keywords") {
    const list = glossaryFor(text || "").map((v) => ({ name: v.name, el: v.el, desc: v.desc, href: itemHref(v) }));
    const gd = S.tables?.armorGuide;
    const extra = [];
    if (gd?.armorCharge?.desc && /armor charge/i.test(text || "")) extra.push({ name: "Armor Charge", el: "", desc: gd.armorCharge.desc });
    // "+20 | +40 | +50 Super" or "Weapons Stat" -> that armor stat's explanation
    (gd?.stats || []).forEach((st) => {
      if (new RegExp(`\\b${st.name} Stat\\b|\\+\\d+(?:\\s*\\|\\s*\\+\\d+)* ${st.name}\\b`).test(text || "")) extra.push({ name: `${st.name} stat`, el: "", desc: st.desc });
    });
    list.unshift(...extra);
    if (!list.length) return "";
    return `<div class="kwdrops" aria-label="${esc(label)}"><span class="kwdrops-label">${esc(label)}</span>${list.map((v) => `<details class="kwd ${v.el ? `el-${esc(v.el)}` : ""}">
      <summary>${esc(v.name)}</summary><div class="desc">${fmt(v.desc)}</div>${v.href ? `<p class="kwd-link"><a href="${v.href}">Open ${esc(v.name)}</a></p>` : ""}</details>`).join("")}</div>`;
  }
  // "makes Jolt · uses Orbs of Power" from the keyword roles (Endgame Trigger/Effect where it covers the entry)
  function rolesLine(e) {
    const r = rolesOf(e);
    const by = (role) => Object.keys(r).filter((k) => r[k].has(role));
    const btn = (k) => `<button type="button" class="chip chip-sm" data-akw="${esc(k)}">${esc(k)}</button>`;
    const mk = by("produce"), us = by("use");
    if (!mk.length && !us.length) return "";
    return `<p class="roles">${mk.length ? `<span class="muted">Makes</span> ${mk.map(btn).join("")}` : ""}${us.length ? ` <span class="muted">Uses</span> ${us.map(btn).join("")}` : ""}</p>`;
  }

  const modIcon = (name) => {
    const k = normName(name.replace(/ Mod$/, ""));
    return S.icons?.mods.get(normName(name)) || S.icons?.mods.get(k) || S.icons?.mods.get(k + "s") || "";
  };
  const setIcons = (name) => S.icons?.sets.get(normName(name.replace(/ Set$/, ""))) || null;

  async function renderArmor(which) {
    which = which === "mods" ? "mods" : "sets";
    await Promise.all([ensureTables(), ensureIcons()]);
    const { q } = parseHash();
    const tabs = [["sets", "Set bonuses", "#/armor"], ["mods", "Mods & stats", "#/armor/mods"]]
      .map(([k, label, href]) => `<a href="${href}" ${k === which ? 'aria-current="page"' : ""}>${label}</a>`).join("");
    const pool = S.entries.filter((e) => e.cat === (which === "sets" ? "armor-set" : "armor-mod"));
    const kwNames = [...new Set(pool.flatMap((e) => Object.keys(e.kw || {})))].sort();
    app.innerHTML = `
      ${crumbs([["Home", "#/"], ["Armor"]])}
      <h1>Armor</h1>
      <p class="intro">${which === "sets"
        ? `Every armor set bonus from the Destiny Data Compendium, with ${esc(S.meta.sources.endgame?.author || "TheAegisRelic")}'s Endgame Analysis trigger, effect and notes for each piece. Open a keyword to see exactly what it does.`
        : `What each armor stat does at every value, how Armor Charge works, and the exact numbers behind every armor mod, from the Destiny Data Compendium.`}</p>
      <nav class="tabbar" aria-label="Armor sections">${tabs}</nav>
      <div class="table-tools">
        <input class="input" type="search" placeholder="${which === "sets" ? "Search sets, perks, sources…" : "Search mods…"}" value="${esc(q.get("q") || "")}" data-aq aria-label="Search">
        <select class="input" data-akwsel aria-label="Keyword" style="max-width:220px"><option value="">Any keyword</option>${kwNames.map((k) => `<option ${k === q.get("kw") ? "selected" : ""}>${esc(k)}</option>`).join("")}</select>
        ${which === "sets" ? `<select class="input" data-asort aria-label="Sort" style="max-width:200px"><option value="">Sort: name</option><option value="tier" ${q.get("sort") === "tier" ? "selected" : ""}>Sort: Endgame tier</option></select>` : ""}
        <span class="muted" data-acount></span>
      </div>
      ${which === "mods" ? armorStatsHTML() : ""}
      <div data-alist></div>
      <p class="source-note">From the Destiny Data Compendium's <a href="${esc(sheetUrl("compendium", which === "sets" ? "Armor Perks" : "Armor Mods") || "#")}" target="_blank" rel="noopener">${which === "sets" ? "Armor Perks" : "Armor Mods"}</a>${which === "mods" ? ` and <a href="${esc(sheetUrl("compendium", "Game Mechanics") || "#")}" target="_blank" rel="noopener">Game Mechanics</a> tabs` : " tab"}${which === "sets" ? `, with ratings from <a href="${esc(sheetUrl("endgame", "Set Bonuses") || "#")}" target="_blank" rel="noopener">Endgame Analysis</a>` : ""}. [Brackets] are PvP values, ↑ marks enhanced values, ? is untested.</p>`;

    const listEl = app.querySelector("[data-alist]");
    const countEl = app.querySelector("[data-acount]");
    const state = { q: q.get("q") || "", kw: q.get("kw") || "", sort: q.get("sort") || "" };
    const sync = () => {
      const p = new URLSearchParams(Object.entries(state).filter(([, v]) => v));
      history.replaceState(null, "", `#/armor${which === "mods" ? "/mods" : ""}${p.toString() ? "?" + p : ""}`);
    };
    const draw = () => {
      const terms = state.q.toLowerCase().split(/\s+/).filter(Boolean);
      let rows = pool.filter((e) => (!state.kw || e.kw?.[state.kw]) &&
        (!terms.length || terms.every((t) => (e._ahay ||= [e.name, e.desc, e.source, e.slot, e.group].join(" ").toLowerCase()).includes(t))));
      countEl.textContent = `${rows.length} of ${pool.length}`;
      listEl.innerHTML = which === "sets" ? armorSetsHTML(rows, state.sort) : armorModsHTML(rows);
    };
    app.querySelector("[data-aq]").oninput = (ev) => { state.q = ev.target.value; sync(); draw(); };
    app.querySelector("[data-akwsel]").onchange = (ev) => { state.kw = ev.target.value; sync(); draw(); };
    const sortEl = app.querySelector("[data-asort]");
    if (sortEl) sortEl.onchange = (ev) => { state.sort = ev.target.value; sync(); draw(); };
    app.onclick = (ev) => {
      const b = ev.target.closest("[data-akw]");
      if (!b) return;
      state.kw = b.dataset.akw;
      app.querySelector("[data-akwsel]").value = state.kw;
      sync(); draw();
      app.querySelector("[data-alist]").scrollIntoView({ block: "start", behavior: "smooth" });
    };
    draw();
  }

  function armorSetsHTML(rows, sort) {
    const best = (e) => Math.min(...(e.eg || []).map((n) => tierRank(n.tier)), 99);
    rows = rows.slice().sort(sort === "tier" ? (a, b) => best(a) - best(b) || a.name.localeCompare(b.name) : (a, b) => a.name.localeCompare(b.name));
    if (!rows.length) return `<p>No sets match. Clear the search or keyword.</p>`;
    return `<div class="armor-grid">${rows.map((e) => {
      const pieces = e.pieces?.length ? e.pieces : [{ count: "", name: "", desc: e.desc }];
      const ic = setIcons(e.name);
      const gear = ic ? ["Hunter", "Titan", "Warlock"].filter((c) => ic.pieces?.[c]).map((c) => `<img src="${BNET}${esc(ic.pieces[c].i)}" alt="" title="${esc(ic.pieces[c].n)} (${c})" width="56" height="56" loading="lazy">`).join("") : "";
      return `<article class="armor-card">
        <header>${gear ? `<div class="set-gear">${gear}</div>` : ""}<div class="set-title"><h2><a href="${itemHref(e)}">${esc(e.name)}</a></h2>${e.source ? `<span class="tag">${esc(e.source)}</span>` : ""}</div></header>
        ${pieces.map((p) => {
          const cnt = (p.count.match(/\d/) || [""])[0];
          const n = (e.eg || []).find((x) => String(x.pieces) === cnt);
          const pi = ic?.perks?.[cnt];
          return `<section class="piece">
            <h3>${pi ? `<img class="perk-ic" src="${BNET}${esc(pi.i)}" alt="" width="32" height="32" loading="lazy">` : ""}<span class="pc">${esc(p.count.replace(/ ?Piece/i, "-piece"))}</span> ${esc(p.name)} ${n?.tier ? tierBadge(n.tier, "Endgame Analysis tier") : ""}</h3>
            <div class="desc">${fmt(p.desc)}</div>
            ${n && (n.trigger || n.effect || n.analysis) ? `<dl class="kv interactions">
              ${n.trigger ? `<dt>Trigger</dt><dd>${esc(n.trigger)}</dd>` : ""}
              ${n.effect ? `<dt>Effect</dt><dd>${esc(n.effect)}</dd>` : ""}
              ${n.analysis ? `<dt>Endgame notes</dt><dd>${esc(n.analysis)}</dd>` : ""}</dl>` : ""}
            ${kwDropsHTML(p.desc)}
          </section>`;
        }).join("")}
        ${rolesLine(e)}
      </article>`;
    }).join("")}</div>`;
  }

  const MOD_SLOTS = ["Helmet", "Arms", "Chest", "Legs", "Class Item"];
  function armorModsHTML(rows) {
    if (!rows.length) return `<p>No mods match. Clear the search or keyword.</p>`;
    const card = (e) => { const i = modIcon(e.name); return `<article class="mod-card">
      <h3>${i ? `<img class="mod-ic" src="${BNET}${esc(i)}" alt="" width="40" height="40" loading="lazy">` : `<span class="mod-ic mod-ic-empty"></span>`}<a href="${itemHref(e)}">${esc(e.name)}</a>${e.cost ? ` <span class="tag">${esc(e.cost)}</span>` : ""}</h3>
      <div class="desc">${fmt(e.desc)}</div>
      ${kwDropsHTML(e.desc)}
    </article>`; };
    const general = MOD_SLOTS.map((slot) => [slot, rows.filter((e) => e.slot === slot)]).filter(([, l]) => l.length);
    const special = new Map();
    rows.filter((e) => !MOD_SLOTS.includes(e.slot)).forEach((e) => {
      const k = e.group || e.slot || "Other";
      (special.get(k) || special.set(k, []).get(k)).push(e);
    });
    return `<h2 class="armor-h2" id="mods">Armor mods</h2>
      ${general.map(([slot, l]) => `<section class="mod-slot"><h3 class="slot-h">${esc(slot)} <span class="muted">${l.length}</span></h3><div class="mod-grid">${l.map(card).join("")}</div></section>`).join("")}
      ${special.size ? `<h2 class="armor-h2">Raid and activity mods</h2>${[...special].map(([g, l]) => `<details class="mod-group"><summary>${esc(g)} <span class="muted">${l.length}</span></summary><div class="mod-grid">${l.map(card).join("")}</div></details>`).join("")}` : ""}`;
  }

  // stat tables come as runs of rows; a row labelled "... Stat" starts a new table and is its header
  function statTablesHTML(rows) {
    const groups = [];
    rows.forEach((r) => { if (/\bStat$/.test(r[0]) || !groups.length) groups.push([r]); else groups[groups.length - 1].push(r); });
    return groups.map((g) => {
      const [head, ...body] = g;
      const width = Math.max(...g.map((r) => r.length));
      return `<div class="tablewrap"><table class="data stat-table"><thead><tr>${Array.from({ length: width }, (_, i) => `<th scope="col">${esc(head[i] || "")}</th>`).join("")}</tr></thead>
        <tbody>${body.map((r) => `<tr><th scope="row">${esc(r[0])}</th>${Array.from({ length: width - 1 }, (_, i) => `<td class="num">${/^-[%x]?$/.test(r[i + 1] || "") ? '<span class="muted" title="Not measured yet">–</span>' : esc(r[i + 1] || "")}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;
    }).join("");
  }
  function armorStatsHTML() {
    const gd = S.tables?.armorGuide;
    if (!gd) return "";
    const statCard = (x) => `<article class="stat-card">
      <h3>${esc(x.name)}</h3>
      <div class="desc">${fmt(x.desc)}</div>
      ${x.rows?.length ? `<details class="stat-nums"><summary>Numbers by stat value</summary>${statTablesHTML(x.rows)}</details>` : ""}
      ${kwDropsHTML(x.desc)}
    </article>`;
    return `<h2 class="armor-h2" id="stats">Armor stats</h2>
      <p class="muted">Each stat works up to 100; past 100 its ↑enhanced benefit kicks in, up to 200.</p>
      <div class="stat-grid">${gd.stats.map(statCard).join("")}</div>
      <div class="stat-grid stat-grid-2">
        ${gd.health ? statCard(gd.health) : ""}
        ${gd.armorCharge ? `<article class="stat-card"><h3>Armor Charge</h3><div class="desc">${fmt(gd.armorCharge.desc)}</div></article>` : ""}
      </div>`;
  }

  // ------------------------------------------------------------ exotic catalysts
  function catalystHTML(w, compParas) {
    const c = w.catalyst;
    if (!c && !compParas.length) return "";
    const stats = (c?.s || []).map(([h, v]) => `<li>${v > 0 ? "+" : ""}${esc(v)} ${esc(S.weapons.statNames[h] || h)}</li>`).join("");
    const perks = (c?.perks || []).map((p) => `<li class="cat-perk">${p.i ? `<img src="${BNET}${esc(p.i)}" alt="" width="36" height="36" loading="lazy">` : ""}<div><b>${esc(p.n)}</b>${p.d ? `<p>${esc(p.d)}</p>` : ""}</div></li>`).join("");
    const generic = /^Defeat targets using this weapon to unlock this upgrade\.?$/i;
    let how = "";
    if (c?.inPerks) how = "Part of the weapon's perk pool, so there's no objective to complete.";
    else if (c) {
      const objs = (c.obj || []).filter(([, n]) => n > 0).map(([d, n]) => `${esc(d || "Progress")}: ${Number(n).toLocaleString()}`).join(" · ");
      const extra = c.unlock && !generic.test(c.unlock) ? esc(c.unlock) : "";
      how = [objs, extra].filter(Boolean).join(". ") || (c.unlock ? esc(c.unlock) : "");
    }
    return `<section class="wcard-sec catalyst">
      <h3>${c?.i ? `<img src="${BNET}${esc(c.i)}" alt="" width="28" height="28">` : ""}${esc(c?.n || "Catalyst")}</h3>
      ${perks ? `<ul class="cat-perks">${perks}</ul>` : ""}
      ${stats ? `<ul class="cat-stats" aria-label="Stat bonuses">${stats}</ul>` : ""}
      ${how ? `<p class="cat-how"><b>How to unlock:</b> ${how}</p>` : c ? `<p class="cat-how muted">Bungie's data doesn't list an unlock objective.</p>` : ""}
      ${compParas.length ? `<div class="cat-comp"><h4>Exact values (Compendium)</h4><div class="desc">${fmt(compParas.map((t) => t.replace(/^\s*↑/, "")).join("\n\n"))}</div></div>` : ""}
      ${!c ? `<p class="muted">Bungie's item data doesn't have a separate catalyst item for this weapon; these values come from the Compendium.</p>` : ""}
    </section>`;
  }

  // ------------------------------------------------------------ pictures for the boss tables
  // icons.json comes from tools/bungie-icons.mjs: ability/aspect icons, exotic armor icons, raid/dungeon art
  async function ensureIcons() {
    if (S.icons) return S.icons;
    let raw = { abilities: {}, armor: {}, activities: {} };
    try { raw = await (await fetch("data/icons.json")).json(); } catch { /* pictures are optional */ }
    const abil = new Map(), act = new Map();
    Object.entries(raw.abilities || {}).forEach(([n, x]) => {
      [n, n.replace(/ Grenade$/, ""), n.split(":")[0]].forEach((k) => { if (!abil.has(normName(k))) abil.set(normName(k), x.i); });
    });
    Object.entries(raw.armor || {}).forEach(([n, i]) => { if (!abil.has(normName(n))) abil.set(normName(n), i); });
    Object.entries(raw.activities || {}).forEach(([n, i]) => { if (!act.has(normName(n))) act.set(normName(n), i); });
    // armor mods: exact names first, then looser keys ("Unflinching Arc Aim" -> "Unflinching Aim", "Heavy Ammo Finder" -> "Ammo Finder")
    const PLACEHOLDER = "bac622a66416ebb9598d710dacd38b0c"; // Bungie's generic "?" mod icon
    const mods = new Map();
    const modEntries = Object.entries(raw.mods || {}).filter(([, x]) => x.i && !x.i.includes(PLACEHOLDER));
    modEntries.forEach(([n, x]) => { if (!mods.has(normName(n))) mods.set(normName(n), x.i); });
    const loose = (n) => [n.replace(/\s*\(.*\)$/, ""), n.replace(/\b(Arc|Solar|Void|Stasis|Strand|Kinetic|Harmonic|Heavy|Special)\b\s*/g, ""), n.replace(/s$/, "")];
    modEntries.forEach(([n, x]) => loose(n).forEach((k) => { const kk = normName(k); if (kk && !mods.has(kk)) mods.set(kk, x.i); }));
    const sets = new Map(Object.entries(raw.sets || {}).map(([n, x]) => [normName(n.replace(/ Set$/, "")), x]));
    S.icons = { abil, act, mods, sets };
    return S.icons;
  }

  const TYPE_WORDS = ["linear fusion rifle", "fusion rifle", "auto rifle", "pulse rifle", "scout rifle", "sniper rifle", "trace rifle",
    "rocket launcher", "grenade launcher", "machine gun", "hand cannon", "submachine gun", "smg", "sidearm", "shotgun", "sniper", "bow", "glaive", "sword"];
  // best-ranked legendary of a type, optionally narrowed by frame
  function genericWeapon(type, frame) {
    type = type.replace(/^sniper$/i, "sniper rifle");
    if (frame) { const w = archetypeWeapon([type, frame]); if (w) return w; }
    const k = typeKey(type);
    const pool = S.weapons.weapons.filter((w) => w.tier === "Legendary" && typeKey(w.type) === k && w.icon);
    pool.sort((a, b) => tierRank(a.eg?.[0]?.tier) - tierRank(b.eg?.[0]?.tier) || (+a.eg?.[0]?.rank || 999) - (+b.eg?.[0]?.rank || 999));
    return pool[0];
  }

  // picture for a weapon/ability name as the boss sheets write it
  function picFor(name, kind) {
    name = (name || "").split("\n")[0].trim();
    if (!name || name === "Base") return "";
    const ic = S.icons;
    const abilityPic = (n) => {
      const keys = [n, n.replace(/ - /, ": "), `${n} grenade`, n.replace(/ melee$/i, ""), n.replace(/ grenade$/i, "")].map(normName);
      for (const k of keys) if (ic.abil.has(k)) return ic.abil.get(k);
      const k0 = normName(n.replace(/ - /, ": "));
      for (const [k, i] of ic.abil) if (k0.length > 5 && (k.startsWith(k0) || k0.startsWith(k) && k.length > 5)) return i;
      return "";
    };
    const img = (src, title, href) => {
      const tag = `<img src="${BNET}${esc(src)}" alt="" width="32" height="32" loading="lazy">`;
      return href ? `<a class="thumb" href="${href}" title="${esc(title)}" aria-label="${esc(title)}">${tag}</a>` : `<span class="thumb" title="${esc(title)}">${tag}</span>`;
    };
    const asWeapon = (n) => S.weaponByKey.get(normName(n));
    if (kind !== "ability") {
      const glaive = name.match(/^Glaive - (.+)$/);
      const w = asWeapon(glaive ? glaive[1] : name);
      if (w?.icon) return weaponThumb(w, 32);
    }
    const a = abilityPic(name);
    if (a) return img(a, name);
    if (kind === "ability") return "";
    // "Aggressive rocket launcher", "Wave frame sword", or the weapon tab's Type + Subtype
    const lower = name.toLowerCase();
    const t = TYPE_WORDS.find((x) => lower.endsWith(x) || lower === x);
    if (t) {
      const g = genericWeapon(t, name.slice(0, lower.length - t.length).trim());
      if (g) return `<span class="thumb-generic" title="Example: ${esc(g.n)}">${weaponThumb(g, 32)}</span>`;
    }
    return "";
  }

  // raid/dungeon art; encounter tab names like "LW - Kalli (+0)" are matched through the boss column
  function activityPic(name, size = "sm") {
    const ic = S.icons;
    const n = normName(name.replace(/ - Epic$/i, ""));
    const src = ic.act.get(n) || [...ic.act].find(([k]) => k.startsWith(n))?.[1];
    if (!src) return "";
    return `<img class="act-${size}" src="${BNET}${esc(src)}" alt="" loading="lazy">`;
  }
  function encounterActivity(tab) {
    const boss = normName(tab.replace(/^[^-]+ - /, "").replace(/\s*\(.*$/, ""));
    const rows = S.tables.health?.rows || [];
    const hit = rows.find((r) => normName(r[2]) === boss) || rows.find((r) => boss && (normName(r[2]).startsWith(boss) || boss.startsWith(normName(r[2]))));
    if (hit) return hit[1];
    // fall back to initials: "GoS" -> Garden of Salvation
    const ab = tab.split(" - ")[0].toLowerCase();
    const acts = [...new Set(rows.map((r) => r[1]))];
    return acts.find((a) => a.split(/\s+/).map((w) => w[0]).join("").toLowerCase().replace(/'/g, "") === ab) || "";
  }

  function archetypeCard(w) {
    const t = S.tables?.archetypes;
    if (!t || !w.frame) return "";
    const frame = normName(w.frame.replace(/ Frame$/, ""));
    const rows = archetypeRowsFor(w.type, w.ammo).filter((r) => normName(r[1].split("/")[0]).startsWith(frame) || frame.startsWith(normName(r[1].split("/")[0])));
    if (!rows.length) return "";
    const col = (name) => t.columns.indexOf(name);
    const show = ["base Damage", "true RPM", "typical MDPS", "typical BDPS", "ADS falloff Range"].filter((n) => col(n) >= 0);
    return `<section class="wcard-sec"><h3>Archetype testing</h3>
      ${rows.map((r) => `<div class="arch-row"><p><b>${esc(r[0])} · ${esc(r[1])}</b> ${tierBadge(r[col("Tier")], "Archetype tier")} ${stunHTML(r[col("Stun")])}</p>
        <dl class="kv">${show.map((n) => r[col(n)] ? `<dt>${esc(n)}</dt><dd>${esc(r[col(n)])}</dd>` : "").join("")}</dl>
        ${r[col("Notes")] ? `<p class="muted small">${esc(r[col("Notes")])}</p>` : ""}</div>`).join("")}
      <p class="small"><a href="#/archetypes">All archetype results</a></p></section>`;
  }

  async function renderArchetypes(tab) {
    if (!S.tables || !S.weapons) app.innerHTML = `<p class="loading">Loading archetypes…</p>`;
    await Promise.all([ensureTables(), ensureWeapons()]);
    const rk = S.weapons.rankings || {};
    const tabs = Object.keys(rk);
    const nav = `<nav class="tabbar arch-tabs" aria-label="Archetype views">
      <a href="#/archetypes" ${!tab ? 'aria-current="page"' : ""}>Archetype testing</a>
      ${tabs.map((k) => `<a href="#/archetypes/${encodeURIComponent(k)}" ${tab === k ? 'aria-current="page"' : ""}>${esc(rk[k].type)}</a>`).join("")}</nav>`;
    const src = S.meta.sources.endgame;
    const head = `${crumbs([["Home", "#/"], ["Archetypes", tab ? "#/archetypes" : null], ...(tab ? [[rk[tab]?.type || tab]] : [])].map(([a, b]) => [a, b || undefined]))}
      <h1>${tab ? `${esc(rk[tab]?.type || tab)} rankings` : "Archetypes"}</h1>
      <p class="intro">From <a href="${esc(sheetUrl("endgame", tab || "Archetypes") || "#")}" target="_blank" rel="noopener">Endgame Analysis</a> by ${esc(src?.author || "TheAegisRelic")}, whose weapon rankings are built on this archetype testing. Laid out the way the sheet is.</p>${nav}`;

    if (!tab) {
      const t = S.tables.archetypes;
      if (!t) { app.innerHTML = head + `<p>The archetype tab isn't in the data yet.</p>`; return; }
      const types = [...new Set(t.rows.map((r) => r[0]))];
      const { q } = parseHash();
      const type = q.get("type") || "";
      const rows = type ? t.rows.filter((r) => r[0] === type) : t.rows;
      app.innerHTML = `${head}
        <div class="table-tools">
          <select class="input" data-atype aria-label="Weapon type" style="max-width:240px"><option value="">All weapon types</option>${types.map((x) => `<option ${x === type ? "selected" : ""}>${esc(x)}</option>`).join("")}</select>
          <input class="input" type="search" placeholder="Filter rows…" data-tfilter aria-label="Filter rows">
          <span class="muted" data-tcount></span>
        </div>
        <div class="tablewrap arch-wrap" data-twrap></div>`;
      // first column is a representative weapon (by slug), drawn as its icon
      const withW = rows.map((r) => [archetypeWeapon(r)?.slug || "", ...r]);
      const cols = ["Example", ...t.columns.map((c, i) => (t.groups[i] && i && t.groups[i] !== t.groups[i - 1] ? `${t.groups[i]}: ${c}` : c))];
      const tierCol = t.columns.indexOf("Tier") + 1;
      const notesCol = t.columns.indexOf("Notes") + 1;
      const stunCol = t.columns.indexOf("Stun") + 1;
      mountTable(app.querySelector("[data-twrap]"), { columns: cols, rows: withW }, app.querySelector("[data-tfilter]"), app.querySelector("[data-tcount]"), {
        tierCol,
        cell: (v, i) => (i === 0 ? weaponThumb(S.weaponBySlug.get(v)) : i === tierCol ? tierBadge(v) : i === stunCol ? stunHTML(v) : i === notesCol ? `<span class="arch-note">${esc(v)}</span>` : esc(v)),
      });
      app.querySelector("[data-atype]").onchange = (ev) => go(`#/archetypes${ev.target.value ? `?type=${encodeURIComponent(ev.target.value)}` : ""}`, true);
      return;
    }

    const list = rk[tab];
    if (!list) { app.innerHTML = head + `<p>No such tab.</p>`; return; }
    const frameStun = (type, frame) => {
      const t = S.tables.archetypes, si = t.columns.indexOf("Stun");
      const f = normName(frame);
      const hit = archetypeRowsFor(type).find((r) => normName(r[1]).startsWith(f) && f);
      return hit ? hit[si] : "";
    };
    const perkCell = (names) => (names || []).map((n) => { const e = compendiumPerk(n); return e ? `<a href="${itemHref(e)}">${esc(n)}</a>` : esc(n); }).join("<br>");
    const archRows = archetypeRowsFor(list.type);
    const t = S.tables.archetypes;
    const ci = (n) => t?.columns.indexOf(n);
    app.innerHTML = `${head}
      ${archRows.length ? `<section class="arch-sum"><h2>${esc(list.type)} archetypes</h2>
        <div class="tablewrap"><table class="data"><thead><tr><th>Example</th><th>Frame</th><th>Stun</th><th>Tier</th><th>Ammo</th><th>Damage</th><th>RPM</th><th>Typical MDPS</th><th>Typical BDPS</th><th>Notes</th></tr></thead>
        <tbody>${archRows.map((r) => { const ex = archetypeWeapon(r); return `<tr><td>${weaponThumb(ex, 48)}</td><td>${esc(r[1])}${ex ? `<br><span class="muted small">e.g. ${esc(ex.n)}</span>` : ""}</td><td>${stunHTML(r[ci("Stun")])}</td><td>${tierBadge(r[ci("Tier")])}</td><td>${esc(r[ci("Ammo")])}</td><td class="num">${esc(r[ci("base Damage")])}</td><td class="num">${esc(r[ci("true RPM")])}</td><td class="num">${esc(r[ci("typical MDPS")])}</td><td class="num">${esc(r[ci("typical BDPS")])}</td><td class="wrap">${esc(r[ci("Notes")])}</td></tr>`; }).join("")}</tbody></table></div></section>` : ""}
      <h2 class="rank-h">Every ${esc(list.type.toLowerCase())}, ranked</h2>
      <div class="table-tools"><input class="input" type="search" placeholder="Filter weapons or perks…" data-rfilter aria-label="Filter weapons"><span class="muted" data-rcount></span></div>
      <div class="tablewrap"><table class="data rank-table">
        <thead><tr><th>#</th><th>Tier</th><th>Weapon</th><th>Season</th><th>Element</th><th>Frame</th><th>Source</th><th>Barrel</th><th>Mag</th><th>MW</th><th>Trait 1</th><th>Trait 2</th><th>Origin</th><th>Notes</th></tr></thead>
        <tbody>${list.rows.map((r) => `<tr data-row="${esc([r.name, r.variant, r.source, r.frame, ...(r.perk1 || []), ...(r.perk2 || []), ...(r.origin || [])].join(" ").toLowerCase())}">
          <td class="num">${esc(r.rank || "")}</td><td>${tierBadge(r.tier)}</td>
          <td class="rk-name"><div class="rk-w">${weaponThumb(S.weaponBySlug.get(r.slug), 36)}<div>${r.slug ? `<a href="#/weapon/${r.slug}">${esc(r.name)}</a>` : esc(r.name)}${r.variant ? `<br><span class="muted">${esc(r.variant)}</span>` : ""}</div></div></td>
          <td class="num">${esc(r.season || "")}</td><td><span class="el-${esc(r.element)}" style="color:var(--c)">${esc(r.element || "")}</span></td><td><span class="rk-frame">${stunHTML(frameStun(list.type, r.frame), false)}${esc(r.frame || "")}</span></td><td>${esc(r.source || "")}</td>
          <td>${esc((r.barrel || []).join(", "))}</td><td>${esc((r.mag || []).join(", "))}</td><td>${esc(r.mw || "")}</td>
          <td>${perkCell(r.perk1)}</td><td>${perkCell(r.perk2)}</td><td>${perkCell(r.origin)}</td><td class="wrap">${esc(r.notes || "")}</td></tr>`).join("")}</tbody>
      </table></div>`;
    const f = app.querySelector("[data-rfilter]"), cnt = app.querySelector("[data-rcount]");
    const all = [...app.querySelectorAll(".rank-table tbody tr")];
    const upd = () => { const v = f.value.toLowerCase().trim(); let n = 0; all.forEach((tr) => { const hit = !v || tr.dataset.row.includes(v); tr.hidden = !hit; n += hit; }); cnt.textContent = `${n} of ${all.length} weapons`; };
    f.oninput = upd; upd();
  }

  // ------------------------------------------------------------ buff stacking (Court's guide)
  const CAT_TONE = ["debuff", "empower", "surge", "amp", "exo", "perk", "world"];
  let stackState = null;
  function loadStackState() {
    if (stackState) return stackState;
    stackState = store.get("d2ce.stack", { mode: "pve", picks: {}, extra: [] });
    return stackState;
  }
  const saveStack = () => store.set("d2ce.stack", stackState);
  const pct = (v) => `${(Math.round(v * 10) / 10).toString()}%`;

  function findEntryByName(name) {
    const k = normName(name.replace(/[*^]+/g, ""));
    if (!k) return null;
    return S.entries.find((e) => normName(e.name) === k) || null;
  }
  function nameLink(name) {
    const clean = name.replace(/[*^]+$/g, "").trim();
    const e = findEntryByName(clean);
    return e ? `<a href="${itemHref(e)}">${esc(clean)}</a>` : esc(clean);
  }

  async function renderStacking() {
    if (!S.stacking) {
      app.innerHTML = `<p class="loading">Loading the stacking guide…</p>`;
      S.stacking = await (await fetch("data/stacking.json")).json();
    }
    const d = S.stacking;
    const st = loadStackState();
    const src = S.meta.sources.court || {};
    const cats = d.categories;

    // every pickable value: category index, entry, variant, tier
    const pickId = (ci, gi, ei, vi, ti) => `${ci}.${gi}.${ei}.${vi}.${ti}`;
    const resolve = (id) => {
      const [ci, gi, ei, vi, ti] = id.split(".").map(Number);
      const e = cats[ci]?.groups[gi]?.entries[ei];
      const v = e?.variants[vi];
      if (!v) return null;
      const pvpT = (v.pvp || "").match(/(\d+(?:\.\d+)?)\s*%/g)?.map((x) => parseFloat(x)) || [];
      return { cat: cats[ci], ci, e, v, pve: v.tiers[ti], pvp: pvpT[ti] ?? pvpT[0] };
    };

    const chosen = [];
    cats.forEach((c, ci) => {
      const ids = st.picks[ci] || [];
      ids.forEach((id) => { const r = resolve(id); if (r && r.pve !== undefined) chosen.push({ id, ...r }); });
    });
    const extras = (st.extra || []).filter((x) => x.value > 0);
    const val = (x) => (st.mode === "pvp" ? (x.pvp ?? 0) : x.pve);
    const factors = [...chosen.map((x) => ({ label: x.e.name, cat: x.cat.name, v: val(x) || 0, id: x.id })), ...extras.map((x, i) => ({ label: x.label || "Custom buff", cat: "Custom", v: x.value, extra: i }))];
    const total = factors.reduce((m, f) => m * (1 + f.v / 100), 1);

    const overview = cats.map((c, ci) => `
      <a class="cat-box tone-${CAT_TONE[ci] || "world"}" href="#stack-${ci}" data-jump="${ci}">
        <span class="cb-rule ${c.exclusive ? "excl" : "free"}">${c.exclusive ? "Strongest one only" : "Stacks with everything"}</span>
        <h3>${esc(c.name)}</h3>
        <p>${esc(c.desc.replace(/\n+/g, " "))}</p>
        <p class="cb-src"><span class="muted">From:</span> ${esc(c.sources.replace(/\n+/g, ", "))}</p>
      </a>`).join("");

    const entryHTML = (c, ci, gi, e, ei) => {
      const isPicked = (vi, ti) => (st.picks[ci] || []).includes(pickId(ci, gi, ei, vi, ti));
      return `<article class="buff">
        <header><h4>${nameLink(e.name)}</h4>${e.source ? `<span class="muted small">${esc(e.source)}</span>` : ""}${e.found ? `<span class="tag">${esc(e.found)}</span>` : ""}</header>
        ${e.variants.map((v, vi) => `
          <div class="bv">
            ${v.trigger ? `<p class="bv-trig">${esc(v.trigger)}</p>` : ""}
            <dl class="bv-vals">
              <div><dt>PvE</dt><dd>${esc((v.pve || "–").replace(/\n+/g, " · "))}${v.pveDur ? ` <span class="muted">for ${esc(v.pveDur.replace(/\n+/g, " · "))}</span>` : ""}</dd></div>
              <div><dt>PvP</dt><dd>${esc((v.pvp || "–").replace(/\n+/g, " · "))}${v.pvpDur ? ` <span class="muted">for ${esc(v.pvpDur.replace(/\n+/g, " · "))}</span>` : ""}</dd></div>
            </dl>
            ${v.tiers.length ? `<div class="bv-add">${v.tiers.map((t, ti) => `<button type="button" class="chip" aria-pressed="${isPicked(vi, ti)}" data-pick="${pickId(ci, gi, ei, vi, ti)}">${isPicked(vi, ti) ? "✓ " : "+ "}${pct(t)}</button>`).join("")}</div>` : ""}
            ${v.notes ? `<p class="small muted">${esc(v.notes)}</p>` : ""}
          </div>`).join("")}
        ${[e.notes, e.misc, e.other].filter(Boolean).map((n) => `<p class="small muted">${esc(n)}</p>`).join("")}
        ${e.intro ? `<p class="small muted">Introduced: ${esc(e.intro.replace(/\n+/g, " "))}</p>` : ""}
      </article>`;
    };

    const listHTML = (c) => {
      const groups = new Map();
      c.lists.forEach((it) => { const g = it.group || "Examples"; (groups.get(g) || groups.set(g, []).get(g)).push(it); });
      return [...groups].map(([g, items]) => `<div class="blist"><h4>${esc(g)}</h4><ul>${items.map((it) => `<li>${nameLink(it.name)}${it.source ? ` <span class="muted small">${esc(it.source)}</span>` : ""}${(it.notes || []).map((n) => `<span class="bl-note">${esc(n)}</span>`).join("")}</li>`).join("")}</ul></div>`).join("");
    };

    const sections = cats.map((c, ci) => `
      <section class="stack-sec tone-${CAT_TONE[ci] || "world"}" id="stack-${ci}">
        <div class="ss-head"><h2>${esc(c.title || c.name)}</h2><span class="cb-rule ${c.exclusive ? "excl" : "free"}">${esc(c.rule.replace(/\n+/g, " "))}</span></div>
        ${c.notes.length ? `<div class="ss-notes">${c.notes.map((n) => `<p>${esc(n)}</p>`).join("")}</div>` : ""}
        ${c.groups.map((g, gi) => `<h3 class="ss-group">${esc(g.name)}</h3><div class="buffs">${g.entries.map((e, ei) => entryHTML(c, ci, gi, e, ei)).join("")}</div>`).join("")}
        ${c.lists.length ? `<div class="blists">${listHTML(c)}</div>` : ""}
      </section>`).join("");

    const ex = d.example;
    const exampleHTML = ex ? `<section class="stack-example">
      <h2>Worked example</h2>
      <p class="muted">${esc(ex.weapon.replace(/\n+/g, ", "))}</p>
      <ol class="ex-chain">${ex.modifiers.map((m, i) => `<li><span>${esc(m.replace(/\n+/g, " "))}</span><b>+${esc(ex.values[i] || "")}</b></li>`).join("")}</ol>
      <p class="ex-total">${esc(ex.total.replace(/\n+/g, " "))}</p>
      <p class="small muted">${ex.values.map((v) => `1.${String(parseFloat(v)).padStart(2, "0")}`).join(" × ")} ≈ ${ex.values.reduce((m, v) => m * (1 + parseFloat(v) / 100), 1).toFixed(2)}x</p>
    </section>` : "";

    const calc = `<aside class="stack-calc" aria-label="Stack calculator">
      <h2>Your stack</h2>
      <div class="seg" role="group" aria-label="Sandbox"><button type="button" aria-pressed="${st.mode === "pve"}" data-mode="pve">PvE</button><button type="button" aria-pressed="${st.mode === "pvp"}" data-mode="pvp">PvP / Gambit</button></div>
      <p class="calc-total"><span>${total.toFixed(2)}x</span><small>${total > 1 ? `+${pct((total - 1) * 100)} damage` : "Add buffs from the boxes below"}</small></p>
      <ul class="calc-list">${factors.map((f) => `<li><span><b>${esc(f.label)}</b><small>${esc(f.cat)}</small></span><span>+${pct(f.v)}</span><button type="button" class="slot-x" aria-label="Remove ${esc(f.label)}" ${f.id ? `data-unpick="${f.id}"` : `data-unextra="${f.extra}"`}>×</button></li>`).join("")}</ul>
      ${factors.length > 1 ? `<p class="small muted calc-math">${factors.map((f) => (1 + f.v / 100).toFixed(3).replace(/0+$/, "").replace(/\.$/, "")).join(" × ")}</p>` : ""}
      <form class="calc-extra" data-extra>
        <label class="small muted" for="xpct">Add an exotic, perk or world buff by hand</label>
        <div><input id="xlabel" class="input" placeholder="Name (e.g. Explosive Light)"><input id="xpct" class="input" type="number" min="0" step="0.1" placeholder="%"><button class="btn" type="submit">Add</button></div>
      </form>
      <p class="small muted">Picking a second Debuff, Empowering buff or Surge replaces the first, because only the strongest of each applies. Melee damage buffs add together rather than multiply, so this total won't be exact for melee.</p>
      ${factors.length ? `<button type="button" class="btn btn-quiet" data-clear>Clear</button>` : ""}
    </aside>`;

    app.innerHTML = `
      ${crumbs([["Home", "#/"], ["Buff stacking"]])}
      <div class="stack-head">
        <h1>Buff stacking</h1>
        <p class="intro">How damage buffs and debuffs combine, from <a href="https://docs.google.com/spreadsheets/d/${esc(src.id || "")}/edit" target="_blank" rel="noopener">Court's Damage Buffs/Debuffs guide</a> by ${esc(src.author || "Court")}. Values are copied as published.</p>
        <div class="stack-rules">
          <div><b>Different categories multiply.</b> A 30% debuff and a 25% empowering buff give 1.30 × 1.25 = 1.625x, not 55%.</div>
          <div><b>Debuffs, Empowering buffs and Surges don't stack within themselves.</b> Only the strongest of each applies.</div>
          <div><b>Everything else stacks</b> with all other buffs and with itself. Melee damage buffs are the exception: they add.</div>
        </div>
      </div>
      <div class="cat-boxes">${overview}</div>
      <div class="stack-layout">
        <div class="stack-main">${exampleHTML}${sections}</div>
        ${calc}
      </div>`;

    const rerender = () => { saveStack(); const y = window.scrollY; renderStacking().then(() => window.scrollTo(0, y)); };
    app.onclick = (ev) => {
      const b = ev.target.closest("button, a[data-jump]");
      if (!b) return;
      const dd = b.dataset;
      if (dd.jump !== undefined) { ev.preventDefault(); document.getElementById(`stack-${dd.jump}`)?.scrollIntoView({ behavior: "smooth" }); return; }
      if (dd.pick) {
        const ci = +dd.pick.split(".")[0];
        const cur = st.picks[ci] || [];
        if (cur.includes(dd.pick)) st.picks[ci] = cur.filter((x) => x !== dd.pick);
        else st.picks[ci] = cats[ci].exclusive ? [dd.pick] : [...cur, dd.pick];
        rerender();
      } else if (dd.unpick) {
        const ci = +dd.unpick.split(".")[0];
        st.picks[ci] = (st.picks[ci] || []).filter((x) => x !== dd.unpick);
        rerender();
      } else if (dd.unextra !== undefined) {
        st.extra.splice(+dd.unextra, 1); rerender();
      } else if (dd.mode) {
        st.mode = dd.mode; rerender();
      } else if (dd.clear !== undefined) {
        stackState = { mode: st.mode, picks: {}, extra: [] }; rerender();
      }
    };
    app.querySelector("[data-extra]").onsubmit = (ev) => {
      ev.preventDefault();
      const v = parseFloat(app.querySelector("#xpct").value);
      if (!(v > 0)) return;
      st.extra.push({ label: app.querySelector("#xlabel").value.trim() || "Custom buff", value: v });
      rerender();
    };
  }

  // ------------------------------------------------------------ about / credits
  function renderAbout() {
    const fetched = S.meta.fetched ? new Date(S.meta.fetched).toLocaleDateString(undefined, { dateStyle: "long" }) : "unknown";
    const cards = Object.entries(S.meta.sources).map(([k, s]) => `
      <article class="source">
        <h2>${esc(s.title)}</h2>
        <p class="by">by ${esc(s.author)}</p>
        <p>${esc(s.blurb)}</p>
        <ul>
          <li><a href="https://docs.google.com/spreadsheets/d/${esc(s.id)}/edit" target="_blank" rel="noopener">Original spreadsheet</a> (${s.tabs.length} tabs)</li>
          <li>${esc(s.contact)}</li>
          ${s.support ? `<li><a href="${esc(s.support)}" target="_blank" rel="noopener">${k === "compendium" ? "Support the Compendium on Patreon" : k === "court" ? "Support Court on Ko-fi" : "Follow their testing on X"}</a></li>` : ""}
        </ul>
      </article>`).join("");
    app.innerHTML = `
      <div class="about">
        <h1>Credits</h1>
        <p>All of the numbers here come from community testers who spend hundreds of hours measuring the game. This site only re-arranges their published spreadsheets so they're easier to search and cross-reference. Corrections belong with the original authors, and the original sheets are always the source of truth.</p>
        <div class="sources">${cards}</div>
        <article class="source" style="max-width:520px">
          <h2>Bungie's Destiny 2 API</h2>
          <p class="by">by Bungie</p>
          <p>Every weapon's name, icon, stats and full perk pool come from the public item manifest${S.meta.bungieVersion ? ` (version ${esc(S.meta.bungieVersion)})` : ""}. Icons and screenshots load straight from bungie.net.</p>
        </article>
        <h2>About this mirror</h2>
        <p>Data last copied on ${esc(fetched)}. Text is copied verbatim; keyword tags and synergy links are generated automatically and can be wrong.</p>
        <p>Unofficial fan project. Not affiliated with Bungie or with the spreadsheet authors. Destiny 2 is a trademark of Bungie, Inc.</p>
      </div>`;
  }

  // ------------------------------------------------------------ router
  function route() {
    const { parts } = parseHash();
    const page = parts[0] || "home";
    const navFor = { item: "explore", wiki: "home", artifact: "home", weapon: "weapons" };
    document.querySelectorAll("[data-nav]").forEach((el) => {
      if (el.dataset.nav === (navFor[page] || page)) el.setAttribute("aria-current", "page"); else el.removeAttribute("aria-current");
    });
    if (page !== "explore") app.onclick = null;
    if (page === "explore") renderExplore();
    else if (page === "item") renderItem(parts[1]);
    else if (page === "wiki") renderCategory(parts[1]);
    else if (page === "artifact") renderArtifact(parts[1]);
    else if (page === "weapons") renderWeapons(parts[1]);
    else if (page === "weapon") renderWeapon(parts[1]);
    else if (page === "archetypes") renderArchetypes(parts[1]);
    else if (page === "stacking") renderStacking();
    else if (page === "armor") renderArmor(parts[1]);
    else if (page === "boss") renderBoss(parts[1]);
    else if (page === "about") renderAbout();
    else renderHome();
    if (page !== "explore" && page !== "weapons") window.scrollTo(0, 0);
  }

  function footer() {
    const s = S.meta.sources;
    document.getElementById("sitefoot").innerHTML =
      `Data from the <a href="https://docs.google.com/spreadsheets/d/${s.compendium.id}/edit" target="_blank" rel="noopener">Destiny Data Compendium</a> and ${esc(s.bossdamage.author)}'s <a href="https://docs.google.com/spreadsheets/d/${s.endgame?.id}/edit" target="_blank" rel="noopener">Endgame Analysis</a>, <a href="https://docs.google.com/spreadsheets/d/${s.bossdamage.id}/edit" target="_blank" rel="noopener">Boss Damage</a> and <a href="https://docs.google.com/spreadsheets/d/${s.bosshealth.id}/edit" target="_blank" rel="noopener">Boss Health</a> sheets. <a href="#/about">Full credits</a>. Unofficial; not affiliated with Bungie.`;
  }

  async function init() {
    try {
      const [ent, meta] = await Promise.all([
        fetch("data/entries.json").then((r) => r.json()),
        fetch("data/meta.json").then((r) => r.json()),
      ]);
      S.entries = ent.entries;
      S.keywords = ent.keywords;
      S.shared = ent.prismaticShared || {};
      S.meta = meta;
      S.entries.forEach((e) => S.byId.set(e.id, e));
      S.keywords.forEach((k) => S.kwByName.set(k.name, k));
      // glossary entries (subclass "verbs") double as keyword definitions
      S.entries.filter((e) => e.cat === "verb").forEach((e) => {
        for (const k of S.keywords) {
          if (!S.glossary.has(k.name) && new RegExp(`^(?:${k.rx})$`, "i").test(e.name.trim())) S.glossary.set(k.name, e);
        }
      });
      buildCombinedRegex();
      footer();
      window.addEventListener("hashchange", route);
      route();
    } catch (err) {
      console.error(err);
      app.innerHTML = `<h1>Couldn't load the data</h1><p>The data files didn't load (${esc(err.message)}). If you opened index.html straight from disk, serve the folder instead, for example <code>python -m http.server</code>, then open the address it prints.</p>`;
    }
  }

  init();
})();
